-- 2410 🏋️ Exercises from the book "fc-barcelona-training-sessions-160-practices-from-34-tactical-situations" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'fc-barcelona-training-sessions-160-practices-from-34-tactical-situations');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Diagonal one-two pass and move square', 'passing_unopposed', 'unopposed', 'in_possession', 16, 16, 'Passing Practices: Practice 1', 'Barcelona (Guardiola era)', 'One-touch one-two combinations with good diagonal passing technique and moving for the return.', 'Small rectangle with players queued at two opposite corners and others at the remaining corners.', 'The player passing diagonally runs on to get the ball back; the player who returns it vertically then jogs across to the far corner. The next player in line restarts the sequence from the new corner and it keeps rotating.', '1 touch for everyone.', NULL, 'Clean diagonal technique; time the pass to the run.', '5 players', 5, 5, '20 x 10 yards', 18.3, 9.1, NULL, false, false, false, NULL, 10),
  ('Diamond one-twos around mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 17, 17, 'Passing Practices: Practice 2', 'Barcelona (Guardiola era)', 'Creating space and moving to get the ball back from one-two combinations.', 'Square with players at four points of a diamond, mannequins between them and a pair of cones in the middle.', 'The start player feeds a central runner who has gone through the cones; he turns and finds a wide player behind a mannequin, who sets it back for the runner. The runner then repeats one-twos with the top and other side players, the last pass goes to the next starter and players rotate positions.', NULL, NULL, 'Pass quality - timing and weight; touch the cone before moving to receive.', '6 players', 6, 6, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 20),
  ('Two-sided double one-two to create space', 'passing_unopposed', 'unopposed', 'in_possession', 18, 18, 'Passing Practices: Practice 3', 'Barcelona (Guardiola era)', 'Making space, receiving, passing and moving to receive the return pass.', 'Mirror-image pattern on both halves of the square, starters in the middle at the bottom, wide and top players with traffic cones to touch.', 'Starters pass to wide players who have moved to touch a cone; the wide player plays a double one-two with the top player (switching feet), then passes to the next starter. Everyone moves on one position, run on both sides at once.', NULL, NULL, 'Synchronise passes and runs on both sides; pass technique and weight.', '8 players', 8, 8, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 30),
  ('Quick combinations around four mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 19, 19, 'Passing Practices: Practice 4', 'Barcelona (Guardiola era)', 'Fast combinations near the touchline, creating space and moving to receive.', 'Small area with four mannequins and a red pole, a starter at the bottom, a central player and two wide players.', 'The starter finds the central player who checks away first; he lays it wide, runs round the pole and gets involved again while a wide player exploits the space the first run made and returns the final ball to the starter. Next sequence goes to the other side, with players swapping positions.', NULL, NULL, 'Open body shape, receive and pass with the back foot; synchronise passes with movement.', NULL, NULL, NULL, '20 x 10 yards', 18.3, 9.1, NULL, false, false, false, NULL, 40),
  ('Turn, pass and move pattern', 'passing_unopposed', 'unopposed', 'in_possession', 20, 20, 'Passing Practices: Practice 5', 'Barcelona (Guardiola era)', 'Technique of turning, passing and moving.', 'Square with two mirrored lanes; starters in opposite corners, receivers behind two red cones, end players by traffic cones.', 'Starters pass to receivers who have just run through the cones; they take it on the half turn and play to the next player, who has touched a cone first. A double one-two follows and the final pass goes to the next starter; all move on one position.', NULL, NULL, 'Quality of turn and pass, weight, communication, rhythm of runs with passes.', NULL, NULL, NULL, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 50),
  ('One-touch combination with overlap', 'passing_unopposed', 'unopposed', 'in_possession', 21, 21, 'Passing Practices: Practice 6', 'Barcelona (Guardiola era)', 'First touch and combination play after an overlapping run.', 'Square with mannequins on each side, wide players by cones and top players beyond the mannequins, starters together at the bottom.', 'Starters pass wide and overlap. The wide player takes a directional touch inside between cones away from the mannequin and finds the top player who has dropped; he touches outward and plays the overlapping runner first time, who passes back to the start. Everyone rotates.', NULL, NULL, 'Accurate, weighted passes; directional first touches to go round the mannequins.', NULL, NULL, NULL, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 60),
  ('Exploit space in one-touch pattern', 'passing_unopposed', 'unopposed', 'in_possession', 22, 22, 'Passing Practices: Practice 7', 'Barcelona (Guardiola era)', 'First touch combined with passing and moving into free space.', 'Large square with mannequins, cones and starters in both bottom corners, central players and wide players behind mannequins.', 'After running through cones the central players are found, lay it to wide players and run into the space behind the mannequins. The wide player takes a directional touch inside through blue cones and passes to forwards arriving from the opposite side; they dribble round a cone and return to the start. Players rotate.', NULL, NULL, 'Accurate, weighted passes; heads up and communication.', NULL, NULL, NULL, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 70),
  ('One-touch pairs passing circuit', 'technical', 'unopposed', 'in_possession', 23, 23, 'Passing Practices: Practice 8', 'Barcelona (Guardiola era)', 'Technique for one-touch passing.', 'Square with pairs of players on small white cones and red traffic cones, laid out on both sides.', 'Each pair sets and plays: one sets the ball in front of his partner who moves round the cone and passes first time to the next pair, and so on back to the start. Both sides run at once; partners swap after each contact.', 'One touch; left side uses left foot, right side right foot.', NULL, 'Open body shape, pass with back foot; set the ball in front of the receiver; rhythm and timing.', NULL, NULL, NULL, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 80),
  ('Numbered passing sequence with three balls', 'technical', 'unopposed', 'in_possession', 24, 25, 'Passing Practices: Practice 9-10', 'Barcelona (Guardiola era)', 'Awareness, close first touch and correct body shape, then directional first touches into space.', 'Marked square with nine numbered players spread out, three balls starting with players 1, 4 and 7.', 'Players pass in number order, receiving from the number before and passing to the one after; with three balls they must be ready again quickly.', '2 touches (receive close to the feet, pass); 1 touch for advanced players.', 'Use more or fewer balls by age/level. Practice 10: the first touch goes towards the next receiver, and after passing the player sprints a few yards before moving to receive again (2 touches).', 'Keep moving and adjusting body shape to see the passer and next receiver.', '9 players', 9, 9, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 90),
  ('7v3 rondo with two inside players', 'rondo', 'overload', 'in_possession', 26, 26, 'Passing Practices: Practice 11', 'Barcelona (Guardiola era)', 'Keeping possession under pressure.', 'Square with five reds on the outside, two reds inside and three defenders inside.', 'Reds keep the ball using the two inside players who move into passing lanes; defenders try to win it. Outside players can shift along their side. Whoever loses the ball swaps with a defender.', '1 touch.', 'More or fewer balls by age/level.', 'Open body shape, back foot; keep moving to find lanes.', '7v3', 10, 10, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 100),
  ('7v3 rondo, inside players'' first touch', 'rondo', 'overload', 'in_possession', 27, 27, 'Passing Practices: Practice 12', 'Barcelona (Guardiola era)', 'First touch and awareness of free space.', 'Square with five reds outside, two reds and three defenders inside.', 'Reds retain possession through the two inside players while the defenders press. Inside players must see the space and take their first touch into it. Loser of the ball swaps with a defender.', 'Inside players 2 touches, outside players 1 touch.', NULL, 'Keep moving to find lanes; use the space the overload creates.', '7v3', 10, 10, '20 x 20 yards', 18.3, 18.3, NULL, false, false, false, NULL, 110),
  ('Double square switching play rondo', 'rondo', 'overload', 'in_possession', 28, 28, 'Passing Practices: Practice 13', 'Barcelona (Guardiola era)', 'Keeping the ball and switching the direction of play.', 'Square with an inner blue square; five reds outside, two reds in the inner square, three defenders in the outer area.', 'Reds look to find the inside players; if the angle is blocked they go round to the free side. A point for 10-15 passes in a row, or for 2-3 completed switches through the inside players.', 'Defenders cannot enter the blue square; outside reds 1 touch; inside players need at least one touch before passing out.', NULL, 'Vision for the free side; constant movement.', '7v3', 10, 10, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 120),
  ('5v5+1 possession with central neutral', 'possession', 'overload', 'in_possession', 29, 29, 'Passing Practices: Practice 14', 'Barcelona (Guardiola era)', 'Body shape to set up the next pass while keeping the ball.', 'Square with a small central zone for the neutral.', 'Two teams of five keep the ball with the neutral joining the side in possession. Point for 10 consecutive passes.', 'Neutral 1 touch; others 2 touches.', NULL, 'Neutral checks options before receiving; quality, timed passing; keep moving.', '5v5+1', 11, 11, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 130),
  ('4v4+4 end-to-end possession', 'positional_game', 'overload', 'in_possession', 30, 30, 'Passing Practices: Practice 15', 'Barcelona (Guardiola era)', 'Moving the ball end to end by forming triangles and diamonds.', 'Rectangle with two neutrals at each end, two teams of four inside, coach on the side with balls.', 'The team in possession tries to get the ball from the neutrals at one end to those at the other for a point, after at least 2 passes inside. They may play back to the neutral they got it from.', 'End neutrals 1 touch or 3 seconds; if slower the coach gives a ball to the other team.', NULL, 'Open body shape; receive and pass with the back foot.', '4v4+4', 12, 12, '25 x 35 yards', 32.0, 22.9, NULL, false, false, true, NULL, 140),
  ('Centre back to forward combination pattern', 'combination', 'unopposed', 'in_possession', 34, 35, 'Attacking Tactical Situation 1: Practices 1-2', 'Barcelona (Guardiola era)', 'Passing combinations built on direct passes from defenders to forwards.', 'Square with four mannequins as opposition midfielders, a marked target box behind them, two poles and a cone; two centre backs, winger, attacking midfielder and centre forward.', 'One centre back passes across; the receiver dribbles forward while the winger and midfielder offer options. He passes to the winger, the striker drops into the target box and combines with the midfielder, and the last ball goes back to the centre back who has circled the pole; he switches it to the other centre back to restart the other way.', NULL, 'Practice 2 (variation, same area): the defensive midfielder makes the run into the target box instead of the striker.', 'Defenders drive forward fast; accurate, weighted, timed passes; time runs and use correct body shape.', '6 players', 6, 6, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 150),
  ('Through the midfield line 3-zone possession', 'positional_game', 'overload', 'in_possession', 36, 36, 'Attacking Tactical Situation 1: Practice 3', 'Barcelona (Guardiola era)', 'Passing through the midfield line.', 'Two end zones of 20 x 20 yards with a 5 x 20 yards central zone containing four mannequins and two neutrals; 3v3 in each end zone, coach with balls.', 'Teams keep the ball in their end zone with the neutrals'' help; after 4 consecutive passes they can play through the gaps between the mannequins to teammates on the other side. The receiver plays it first time to a neutral, then the team needs 4 passes before going back.', 'Neutrals 1 touch; receivers of the vertical pass 1 touch; coach feeds a new ball when it goes out.', NULL, 'Intelligent movement to open lanes; passes timed with runs.', '3v3+3v3+2', 14, 14, '40 x 45 yards', 41.1, 36.6, NULL, false, false, true, NULL, 160),
  ('Build up from the back 3-zone SSG', 'phase_of_play', 'overload', 'in_possession', 37, 37, 'Attacking Tactical Situation 1: Practice 4', 'Barcelona (Guardiola era)', 'Direct passes from defenders to forwards, skipping midfield.', 'Area with three zones and a goal at each end; 3v3 in the high zone, 3v3 in the middle (blue) zone, 3v2 in the low zone, goalkeepers.', 'Red defenders try to pass straight into the forwards in the high zone with help from the middle three, who act as neutrals and give it back but may not pass to the forwards. Once the forward ball goes in, zone restrictions end and reds try to score; whites counter if they win it.', 'First stage: reds in the middle zone 1 touch; forwards 1 touch on the vertical pass; low zone free.', NULL, 'Smart movement into open lanes; synchronised support.', '10v9', 19, 21, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 170),
  ('Direct to forwards 11v11 receiving zone game', 'conditioned_game', 'opposed', 'in_possession', 38, 38, 'Attacking Tactical Situation 1: Practice 5', 'Barcelona (Guardiola era)', 'Defenders passing straight into the forwards to reach the third phase of attack quickly.', 'Two thirds of a pitch split into three zones: 4v3 in the low zone, 3v3 in the middle (blue) zone, 4v3 in the high zone, with goalkeepers.', 'Red defenders try to pass directly to forwards in the high zone; the middle three help them find lanes but cannot play forward themselves. Once a forward receives, or the whites win the ball, all zone limits are lifted.', 'Forwards 1 touch on the vertical pass; midfielders 1 touch when helping the defenders.', NULL, 'Defenders scan for the pass through the line; forwards check away before receiving.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Centre back dribble out and one-two', 'passing_unopposed', 'unopposed', 'in_possession', 41, 41, 'Attacking Tactical Situation 2: Practice 1', 'Barcelona (Guardiola era)', 'Defenders playing out and carrying the ball forward to create an extra man in midfield.', 'Area with two small goals at the top, two pairs of red cones, poles, two centre backs, a defensive midfielder and a wide player with balls.', 'Centre back passes across; the receiver dribbles between the cones and plays a one-two with the midfielder, then passes into a small goal, sprints round the pole and receives a long ball from the wide player, passing it to the other centre back to restart on the left. High tempo.', NULL, NULL, 'Keep the ball close on the dribble; good technique receiving and passing in the air.', '5 players', 5, 5, '40 x 30 yards', 36.6, 27.4, NULL, true, false, true, NULL, 190),
  ('Defenders join midfield 3v3+4 possession', 'possession', 'overload', 'in_possession', 42, 42, 'Attacking Tactical Situation 2: Practice 2', 'Barcelona (Guardiola era)', 'Defenders stepping into midfield to create superiority and move the ball forward.', 'Rectangle with 3v3 inside; four red neutrals outside acting as the defensive line, balls around.', 'A defender dribbles in and combines with the inside team to find the free player and pass out to a defender on the other side, then returns to his spot; the next defender does the same. If the whites win it they need 2 passes then can use the neutrals, who combine with them.', 'Neutrals pass among themselves with 1 touch before one dribbles in.', NULL, 'Dribble forward fast to create the overload; midfielders check away before receiving.', '3v3+4', 10, 10, '20 x 30 yards', 27.4, 18.3, NULL, false, false, true, NULL, 200),
  ('Extra man in midfield and finish', 'phase_of_play', 'overload', 'in_possession', 43, 43, 'Attacking Tactical Situation 2: Practice 3', 'Barcelona (Guardiola era)', 'Defenders joining midfield to create an overload and move the ball forward.', 'Marked area with 4v4 inside, a goal with goalkeeper beyond the end line, two defenders and the coach in a small box at the other end.', 'Coach feeds the defenders, who dribble in or pass with 1 touch waiting for the moment; it becomes 5v4. Blues try to dribble over the end line and shoot unopposed. If the whites win it they try to pass to the coach and become the attackers.', 'If the blues win it back before the whites reach the coach, they return it to the coach to restart.', NULL, 'Always keep a free player; midfielders check away before receiving.', '5v4+GK', 10, 11, '30 x 40 yards', 36.6, 27.4, NULL, true, true, true, NULL, 210),
  ('Defender steps in, 3-zone 11v11 game', 'conditioned_game', 'overload', 'in_possession', 44, 44, 'Attacking Tactical Situation 2: Practice 4', 'Barcelona (Guardiola era)', 'Defenders moving into midfield to create superiority and build an attack on the right.', 'Two thirds of a pitch with two equal end zones and a smaller central zone; 4v3 in each end zone, 3v3 in the middle, goalkeepers.', 'One red defender carries the ball into the middle zone to make an overload; reds combine there to free a player who dribbles into the high zone for a 4v4 finish. Whites counter attack on winning it, when zone limits end. Restart from the red goalkeeper.', NULL, NULL, 'Player stepping out of his zone creates the free man; keep balance for the negative transition.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Switching positions combination pattern', 'combination', 'unopposed', 'in_possession', 47, 47, 'Attacking Tactical Situation 3: Practice 1', 'Barcelona (Guardiola era)', 'Attacking combinations built on switching positions between forwards and midfielders.', 'Two red end zones and two central zones; four green players outside, two yellow link players in the end zones, two pairs of reds centrally. Two balls, one per side.', 'Starters pass to reds dropping into the end zone, who lay it back and push into the central zone; the central pair then drop into the end zones, receive on the turn and find the link players, who play 1 touch back to the next reds; the ball finishes with the outside players and the drill continues.', NULL, NULL, 'Pass weight synced with timed runs; quality turns and passes. Players rotate roles.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, true, NULL, 230),
  ('2(+5)v4 change direction possession', 'possession', 'overload', 'in_possession', 48, 48, 'Attacking Tactical Situation 3: Practice 2', 'Barcelona (Guardiola era)', 'Changing the direction of play while switching positions.', 'Square with a red end zone at the top; 2 reds and 4 whites inside, five red teammates around the outside.', 'Reds keep the ball with outside help; players in the red zone drop in one at a time to offer options. Point for 15-20 consecutive passes. If whites win it they play 4v3 inside aiming for 5 passes.', 'Reds 2 touches; whites unlimited; other three outside players stay on their side and cannot enter.', NULL, 'Synchronised movement when switching positions; quality, timed passing.', '2(+5)v4', 11, 11, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 240),
  ('Switching positions end zone game', 'positional_game', 'opposed', 'in_possession', 49, 49, 'Attacking Tactical Situation 3: Practice 3', 'Barcelona (Guardiola era)', 'Forwards dropping deep and switching positions to progress.', 'Area split into low and high zones plus a 10 x 35 yards end zone; 3v3 plus one outside in the low zone, 3v3 in the high zone.', 'Reds keep the ball in the low zone and get it into the high zone after a switch of positions: a high-zone player drops in, receives and moves up to make 4v3, aiming to dribble across the end line. Only one red may enter or drop between zones.', 'Whites stay in their zone until they win it; offside applies; if the switch fails players reset.', NULL, 'Receive on the half turn when dropping; synchronise switches; forwards offer options at once.', '7v6', 13, 13, '45 x 35 yards', 41.1, 32.0, NULL, false, false, true, NULL, 250),
  ('Dropping deep 2-zone SSG', 'phase_of_play', 'overload', 'in_possession', 50, 50, 'Attacking Tactical Situation 3: Practice 4', 'Barcelona (Guardiola era)', 'Dropping deep to create space through switching positions.', 'Goal-to-goal area split into a low white zone (25 x 45 yards, 5v3) and a high blue zone (30 x 45 yards, 4v5) with goalkeepers.', 'Reds keep the ball low and, after a player drops from the high zone and switches positions, get it into the high zone to make 5v5 and score. Whites try to score on winning it.', 'Only one red can enter or drop between zones; whites stay in zones until they win the ball; failed switch = reset.', NULL, 'Receive on the half turn; synchronised movement; forwards give options quickly.', '10v9', 19, 21, '55 x 45 yards (two zones)', 50.3, 41.1, NULL, true, true, true, NULL, 260),
  ('Forwards drop deep pattern round mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 53, 53, 'Attacking Tactical Situation 4: Practice 1', 'FC Barcelona', 'Forwards learn to drop between the lines to give an extra option and keep the ball in midfield.', '30 x 40 yard area with two lines of mannequins in the middle; A and A1 start at opposite ends with a ball each, B/B1 inside, C/C1 and D/D1 wide.', 'A and A1 dribble in while B and B1 drop below the mannequins to receive; they lay off to C/C1, who pass to D/D1, who return the ball to the start. A and A1 then time their own drop at the other end; players rotate A to B to C to D.', NULL, NULL, 'Open body shape when dropping so the first pass can be one touch; passes and drops must be in sync.', '8+ players', 8, NULL, '30 x 40 yards', 36.6, 27.4, NULL, false, false, false, NULL, 270),
  ('Neutral forwards drop in to keep possession', 'possession', 'overload', 'in_possession', 54, 54, 'Attacking Tactical Situation 4: Practice 2', 'FC Barcelona', 'Forwards drop deep to create a numbers-up and help keep the ball in midfield.', '30 x 30 yard main area plus a 5 x 30 yard zone at one end where 2 neutral forwards wait; 4 reds v 4 whites inside, 1 outside player with balls.', 'Reds try to string 10 passes with help from the neutrals, who drop into the main area one at a time, play the ball and leave again. If whites win it they play 4 (+1 neutral) v 4 and aim for 5-8 passes.', 'Outside player one touch; a neutral may stay in the main area only 5 seconds. Pass target can be adjusted to age/level.', NULL, 'Neutrals must time their runs into the area.', '4v4 +2 neutrals +1 outside', 11, 11, '30 x 30 yards + 5 x 30 yard end zone', 32.0, 27.4, NULL, false, false, false, NULL, 280),
  ('Dropping deep with quick break, 3 zones', 'small_sided_game', 'opposed', 'in_possession', 55, 55, 'Attacking Tactical Situation 4: Practice 3', 'FC Barcelona', 'Forward drops deep for a midfield overload, then the team breaks quickly forward to score.', '60 x 40 yards in 3 zones: 5v5 in the low zone, the red forward in the middle (red) zone, 1 white defender and a keeper in the far zone; 2 small goals for whites at the near end.', 'Reds need 3-4 passes (with the forward touching it at least once) before passing forward into the other zones and attacking the keeper; once the pass goes forward everyone can join. Whites who win it score in either small goal freely.', 'Forward may stay in the low zone 5 seconds, then must go back to the middle; offside applies before the forward pass.', 'Raise the pass count for higher levels.', NULL, '5v5 + 1 forward + 1 defender + GK', 13, 13, '60 x 40 yards', 54.8, 36.6, NULL, true, true, true, NULL, 290),
  ('Dropping deep with quick break, 11v11', 'conditioned_game', 'opposed', 'in_possession', 56, 56, 'Attacking Tactical Situation 4: Practice 4', 'FC Barcelona', 'Forward drops deep to make a numbers-up and keep the ball before breaking into the high zone.', 'Two-thirds of a pitch split into a low zone (6v6) and a high zone (4v4), goal and keeper at the far end, goal at the near end.', 'Players stay in their zone except one red who may drop into the low zone; reds need 4-6 passes (the dropping player touching it) before passing into the high zone, after which all may push up. Whites who win it counter freely.', 'White high-zone defenders cannot enter the low zone unless their team has the ball.', NULL, 'Forwards time their drop; everyone keeps moving to make passing options.', '11v11', 22, 22, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Back three creates space for midfielder', 'passing_unopposed', 'unopposed', 'in_possession', 59, 60, 'Attacking Tactical Situation 5: Practice 1', 'FC Barcelona', 'Using three at the back, a centre back''s forward run opens space in the low zone for the holding midfielder.', '40 x 40 yard area with two marked boxes for the outside centre backs (16 and 3), a central back (5), midfielders 6 and 8 by cones, forward 10 and a coach.', 'Ball goes to 5; 22 pushes on, 16 drops into the space he left, receives from 5 and plays 8 who checks off his cone and sets back to 22; 22 finds 6 in the freed space, 6 to 8 to the coach. Repeat to the right side with 6 the one dropping.', '1-2 touches throughout.', 'Practice 2 (variation): same set-up, 5 plays straight to 22 who has run round a pole, 8 checks with an up-and-down move and plays 6, 6 to 16, 16 to 8 to the coach.', 'Rhythm and timing of pass and run; open body shape to allow one touch.', '8-9 players + coach', 8, NULL, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 310),
  ('Creating space end zone game 6v7', 'positional_game', 'opposed', 'in_possession', 61, 61, 'Attacking Tactical Situation 5: Practice 3', 'FC Barcelona', 'Synchronised movement with three at the back to create space low and an overload by the touchline.', '40 x 40 yards with an end zone at each end; two blue boxes for the centre backs and cones for the holding midfielder; reds 3-2-2 v whites 2-3-1; coach with balls.', 'Coach calls a side and passes to the central defender, who directs play that way; reds use the space left by the centre back''s run to make 3v2 wide and dribble into the far end zone. Whites win it and counter by dribbling over the near end line.', 'Reds have 10 seconds or the coach gives the whites a ball; offside on; ball out = restart from coach.', NULL, 'Synchronised movement; make passing options, not just numbers; keep balance.', '6v7', 13, 13, '40 x 40 yards', 36.6, 36.6, NULL, false, false, true, NULL, 320),
  ('Creating space in the low zone SSG', 'small_sided_game', 'opposed', 'in_possession', 62, 63, 'Attacking Tactical Situation 5: Practice 4', 'FC Barcelona', 'Back three makes space in the low zone for the holding midfielder and a spare man near the touchline.', 'Part of a pitch with a big goal and keeper at one end, a goal at the other; two blue areas near the red back line.', '8v7: reds build out, a centre back leaves his blue area and the holding midfielder drops into it, giving a strong-side overload; reds aim to score, whites win it and counter. Near the box the midfielder can leave the area to keep the team together.', 'The strong-side blue area must be filled during the first build-up phase.', 'Practice 5 (variation): 9v8 with reds using four at the back.', 'Synchronised movement; real passing options; balance at the back.', '8v7 (9v8)', 15, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Creating space in the low zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 64, 64, 'Attacking Tactical Situation 5: Practice 6', 'FC Barcelona', 'Three-at-the-back build-up where a full back''s move opens space for the holding midfielder.', '11v11 with two blue areas at the red end; whites may not enter them unless the red keeper passes to a team-mate there.', 'When 22 or 3 leaves his blue area the nearby holding midfielder drops in, making a strong-side overload while keeping balance. Reds try to score, whites win it and counter.', 'Whites barred from the blue areas until the keeper plays into one.', 'Reds play with four at the back.', 'Synchronised movement; real passing options; balance at the back.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Full backs free wingers, cross and finish', 'combination', 'unopposed', 'in_possession', 67, 67, 'Attacking Tactical Situation 6: Practice 1', 'FC Barcelona', 'Full backs'' forward runs make space for wingers to drop in and receive, ending in a cross and shot.', 'Mirror patterns on both sides of a pitch section with a goal and keeper at the top, red poles out wide, blue boxes for the wingers and two holding midfielders in the middle.', 'Centre backs pass forward and get it back, triggering the full backs to run round the pole; wingers drop into the space, receive and play into the forwards, and the move finishes with the full back''s low cross for the strikers to shoot.', NULL, NULL, 'Timing of runs with the pass; body shape for one touch.', 'about 16 players', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Winger drops, full back goes, 2 zone SSG', 'small_sided_game', 'overload', 'in_possession', 68, 68, 'Attacking Tactical Situation 6: Practice 2', 'FC Barcelona', 'Full back and winger rotate so the winger can receive in space on the flank.', 'Two zones with 2 mini goals at the far end; whites 2-3-1, reds 4-1-3; coach at the near end line.', '8v6: reds work the ball into the high zone to score in a mini goal. When a red full back steps up, his winger drops into the low zone; if the white winger follows, space opens low, if not a 4v3 appears high.', 'Only red full backs and white wingers can change zones (red wingers can drop low then go back up); no zone limits if whites win it; restarts from the coach.', NULL, 'Full back and winger move in sync; winger arrives free and able to turn; keep balance.', '8v6', 14, 14, NULL, NULL, NULL, NULL, true, false, true, NULL, 360),
  ('Creating space on the flank, high & low zones', 'conditioned_game', 'opposed', 'in_possession', 69, 69, 'Attacking Tactical Situation 6: Practice 3', 'FC Barcelona', 'Full backs push up so the wingers can drop and receive unmarked.', '9v9 on part of a pitch split by a line into high and low zones; goal and keeper at the far end, goal at the near end; whites 4-3-1, reds 4-1-3.', 'When a red full back enters the high zone the winger on that side drops back in sync to receive. When defending, only white wingers may change zones; after a turnover no limits.', 'Zone limits for whites only while defending.', NULL, 'Open on the half turn to see the next pass; sync full back and winger; balance at the back.', '9v9', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Wingers dropping deep, 2 zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 70, 70, 'Attacking Tactical Situation 6: Practice 4', 'FC Barcelona', 'Wingers drop into space vacated by marking full backs while reds build with four at the back.', '2 zone 11v11 game, goals with keepers at each end.', 'Red wingers and full backs combine to use space left by the full backs'' runs into the high zone while staying balanced at the back. Free play if whites win it.', 'White defenders cannot enter the low zone; others move freely.', NULL, 'Open body shape; judgement on when to drop or go forward; balance.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Receiving with open body shape in pairs', 'passing_unopposed', 'unopposed', 'in_possession', 73, 73, 'Attacking Tactical Situation 7: Practice 1', 'FC Barcelona', 'Correct open body shape when receiving.', '30 x 30 yards; pairs by bib colour inside, neutral players on the outside, pairs of small cones forming gates.', 'Player in possession passes to a neutral, who plays it back through the gate; the receiver shifts sideways to open up, makes eye contact with his partner and gets the return, then passes to the partner who has moved into a lane; the new man in possession picks another neutral.', 'Neutrals use 2 touches to give time.', NULL, 'Open stance; eye contact before receiving; quality passing and synced movement.', 'pairs + 4 neutrals', 10, NULL, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 390),
  ('Body shape 4v4 (+5) possession', 'possession', 'overload', 'in_possession', 74, 74, 'Attacking Tactical Situation 7: Practice 2', 'FC Barcelona', 'Correct body shape when receiving.', '30 x 30 yards with 4v4 plus 1 neutral inside and 4 neutrals on the sides.', 'Team on the ball keeps possession with the 5 neutrals; after passing to an outside neutral players open up to see options. 10-20 passes scores a point; only passes among inside players count.', 'Inside neutral 1 touch, inside players 2 touches, outside players must return it within 3 seconds.', NULL, 'Keep moving; angles and body shape; eye contact before receiving.', '4v4+5', 13, 13, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 400),
  ('Receiving zone body shape dynamic game', 'phase_of_play', 'opposed', 'in_possession', 75, 75, 'Attacking Tactical Situation 7: Practice 3', 'FC Barcelona', 'Correct body shape when receiving to play forward to the strikers.', '40 x 50 yards in 3 zones: in the deep zone 3 white defenders, a keeper and 2 red forwards; in the blue low zone 4v3; outside players at the back.', 'Reds receive from the outside players with open shape, aware of the forwards, and pass into one of them as they make room; once a forward has it zones are free. Whites win it and dribble over the end line.', 'Players stay in zones at first; outside players pass only into the blue area within 3 seconds (1 touch between each other); forwards one touch at first.', NULL, 'Keep moving; body shape and angles; eye contact.', '8v6 (6v7 +2)', 14, 14, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 410),
  ('Receiving zone build-up 11v11', 'conditioned_game', 'opposed', 'in_possession', 76, 76, 'Attacking Tactical Situation 7: Practice 4', 'FC Barcelona', 'Correct body shape to receive and feed the forwards during build-up.', 'Three zones: 2v1 in the low zone, 4v3 in the middle blue zone, 4v6 in the high zone; goals and keepers each end.', 'Reds pass into the middle zone and on to the forwards; once the forwards get it, all play freely to score. Whites who win it counter.', 'Low zone free; middle zone 2 touches; forwards 1 touch in the first phase; no pass straight from low to high zone.', NULL, 'Middle players open up to see the forwards; quality passing and angles.', '11v11', 22, 22, 'Full pitch, 3 zones', NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Numbers-up on the flank combination', 'passing_unopposed', 'unopposed', 'in_possession', 79, 80, 'Attacking Tactical Situation 8: Practice 1', 'FC Barcelona', 'Rehearse the movements that make an overload on the flank.', '40 x 40 yards, pattern run on both sides; red cones, traffic cones, a mannequin each side and forwards at the top.', '16 dribbles through cones and passes to the winger, who checks off a cone; the winger feeds the midfielder''s diagonal run behind the mannequin, he drives at a traffic cone, changes direction and plays a double one-two with the forward, who passes through cones back to the start. Rotate positions.', NULL, 'Practice 2 (variation): full back 22 dribbles, plays the winger, then overlaps to receive, and plays a double one-two with 8 before the return through the cones.', 'Quality passing, synced movement, attack the free space.', '10-12 players', 10, NULL, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 430),
  ('Flank combination play to a finish', 'combination', 'unopposed', 'in_possession', 81, 83, 'Attacking Tactical Situation 8: Practice 3', 'FC Barcelona', 'Create and use an overload on the flank and finish.', 'Half pitch, mannequins as defenders, goal with keeper, run from both sides.', '16 plays 8 and gets it back, passes to the winger who checks off a cone; 8 runs diagonally behind the full-back mannequin, receives, dribbles inside and plays the striker who lays it back for a shot.', 'One touch where possible.', 'Practice 4 (variation): 16-10-16 then a long ball to the winger, who dribbles in and plays the overlapping full back for a low cross to the striker. Practice 5: same but the full back makes an inside run behind the mannequin.', 'Attack synced space; one touch to speed up; quality crossing and finishing.', '8-10 + GK', 8, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Switch to the weak side 9v8', 'conditioned_game', 'overload', 'in_possession', 84, 84, 'Attacking Tactical Situation 8: Practice 6', 'FC Barcelona', 'Overload the flank by switching to the weak side, with overlaps and diagonal runs.', 'Part of a pitch with a goal and keeper each end; reds 3-2-3 v whites 3-3-1.', 'Reds attack and try to score; with only three white defenders the reds switch quickly and use overlapping full backs or diagonal runs by midfielders to get wide overloads. Whites win it and counter.', NULL, NULL, 'Switch often to the weak side; keep moving and attack space.', '9v8', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 450),
  ('2v1 on the flank, side zone game', 'conditioned_game', 'opposed', 'in_possession', 85, 85, 'Attacking Tactical Situation 8: Practice 7', 'FC Barcelona', 'Create 2v1s on the flank with diagonal, overlapping and inside runs.', '11v11 on two-thirds of a pitch with two 15 x 40 yard side zones; goal and keeper each end.', 'Only white full backs may enter the side zones, so reds create 2v1s there and get in behind to score. Free play once whites win it.', 'One white defender per side zone.', NULL, 'Switch play often; keep moving and attack space.', '11v11', 22, 22, '2/3 pitch, side zones 15 x 40 yards', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Switching play 4 corner zones possession', 'positional_game', 'overload', 'in_possession', 88, 88, 'Attacking Tactical Situation 9: Practice 1', 'FC Barcelona', 'Switch play diagonally by giving the man on the ball at least 3 options.', '30 x 30 yards with a square in each corner holding a neutral; 4v4 inside; coach with balls.', 'Team in possession uses all neutrals and forms triangles and diamonds; a point is scored by moving the ball from one corner neutral to the opposite one after at least 2 inside passes.', 'Neutrals pass within 3 seconds or the coach gives the other team a new ball.', NULL, 'Open up and receive on the back foot; keep moving into passing lanes.', '4v4+4', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 470),
  ('Passing options dynamic end line game', 'positional_game', 'overload', 'in_possession', 89, 89, 'Attacking Tactical Situation 9: Practice 2', 'FC Barcelona', 'Switch play using at least 3 passing options, then attack.', '30 x 40 yards, 6v6 with a neutral on each side line; end lines at both ends; coach with balls.', 'Move the ball from one neutral to the other with at least 2 passes in between, then try to dribble over the end line. Teams can play back to the neutral they got it from.', 'Neutrals pass within 3 seconds or the coach restarts with the other team.', NULL, 'Take positions that make the switch possible; body shape for one touch.', '6v6+2', 14, 14, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 480),
  ('Switching play 7v7 (+2) SSG', 'small_sided_game', 'overload', 'in_possession', 90, 90, 'Attacking Tactical Situation 9: Practice 3', 'FC Barcelona', 'Switch play using at least 3 passing options, then score.', '35 x 45 yards, goals with keepers each end, 6v6 inside plus a neutral in each side channel.', 'Teams must move the ball from one neutral to the other with at least 2 passes between, then go for goal; they may play back to the neutral they received from.', 'Neutrals pass within 3 seconds or the coach gives the other team a ball.', NULL, NULL, '6v6+2+2 GK', 16, 16, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 490),
  ('Switching play 9v9 (+2) side zone game', 'conditioned_game', 'overload', 'in_possession', 91, 91, 'Attacking Tactical Situation 9: Practice 4', 'FC Barcelona', 'Switch play to the flank using at least 3 passing options.', 'Part of a pitch with goals and keepers; 8v8 inside plus a neutral in each side zone.', 'Teams move the ball from one neutral to the other with at least 2 passes between, then try to score; can return to the neutral they received from.', 'Neutrals 2 touches or pass within 3 seconds.', NULL, NULL, '8v8+2 +GKs', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Receive, turn and pass in limited space', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Attacking Tactical Situation 10: Practice 1', 'FC Barcelona', 'Turning and passing in tight space and time.', '40 x 40 yards with two small blue squares in the middle and mannequins; two balls running different patterns at once.', 'A passes to B who turns in the square and plays C; B and C do a double one-two and it ends at the far end. At the same time D plays E who turns in the square and finds F, who runs behind a mannequin, dribbles to the next one, feints and passes across.', 'First and last passes as close to simultaneous as possible; square size to level.', NULL, 'Soft touches when turning; passes timed to runs.', '10-12 players', 10, NULL, '40 x 40 yards', 36.6, 36.6, NULL, false, false, false, NULL, 510),
  ('Receive, turn, switch play 8v4', 'rondo', 'overload', 'in_possession', 95, 95, 'Attacking Tactical Situation 10: Practice 2', 'FC Barcelona', 'Turn and pass in limited space and time to switch play.', '30 x 30 yards with a smaller red centre square; 7 reds outside, 1 red inside the square, 4 whites in the area.', 'Reds keep it and try to find the man in the square, who turns and switches it to the other side. Points for 15 passes in a row or for two successful switches through the inside player.', 'Inside player 2 touches; outside reds can shift sideways; whites may never enter the square; whites swap with 4 reds every 2 minutes.', NULL, 'Keep moving into lanes; quality passing and turning.', '8v4', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 520),
  ('Receive, turn and pass 3 zone switch game', 'positional_game', 'overload', 'in_possession', 96, 96, 'Attacking Tactical Situation 10: Practice 3', 'FC Barcelona', 'Switch play by turning, passing and keeping the ball.', '30 x 30 yards with a 7 x 30 yard central zone holding a neutral, 3v3 in each end zone, a neutral outside each end; coach with balls.', 'Reds keep it and find the central neutral, who turns and plays a red on the far side; those reds must use their end neutral before returning it to the central neutral. Roles switch on a turnover or if the 20 second limit runs out (coach gives the other team a ball).', 'Outside neutrals 1 touch or 3 seconds; central neutral and team in possession 2 touches.', NULL, NULL, '3v3+3v3 +3 neutrals', 15, 15, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 530),
  ('Passing through the midfield line possession', 'positional_game', 'overload', 'in_possession', 97, 97, 'Attacking Tactical Situation 10: Practice 4', 'FC Barcelona', 'Pass in behind the opponent''s midfield line and receive there.', 'Same 30 x 30 area: 4v2 in each end zone, 3 whites in the central zone plus 1 at the side.', 'Low-zone reds keep it and pass past the central whites to reds in the far zone, who receive, keep it and pass back. If the whites win it, they play 5v4 with the three middle players moving into an end zone and try for 10 passes.', 'Optional: 4 passes or a switch inside 20 seconds, else the coach gives whites a 6v4 ball.', 'Variation: when whites win it they play 5v4 in one zone while the coach sends a ball to the other zone for a 4v3 for the reds (outside white joins); keep possession as long as possible and swap roles on a white win.', NULL, '8v7 +1', 16, 16, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 540),
  ('Passing through the midfield line dynamic SSG', 'small_sided_game', 'overload', 'in_possession', 98, 98, 'Attacking Tactical Situation 10: Practice 5', 'FC Barcelona', 'Turn, pass and approach the final third.', '6v6 (+GK) in the low zone with a red receiving zone beyond and 3 more red forwards behind it; big goal with keeper for whites, 2 small goals at the far end for reds.', 'Reds keep it and find one of the three forwards dropping into the red area to receive on the turn and score in a small goal. Whites defend, win it and counter at the big goal.', 'Reds max 2 touches; whites free.', NULL, 'Drop at the right time for a numbers-up; keep moving and make angles.', '9v6 +GK', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Passing through midfield line receiving zone 11v11', 'conditioned_game', 'opposed', 'in_possession', 99, 99, 'Attacking Tactical Situation 10: Practice 6', 'FC Barcelona', 'Turn, pass and approach the final third.', 'Two-thirds of a pitch with two 10-yard zones; 6v4 for reds in the low zone, 4v4 in the high zone; 2 white holding midfielders in the white zone; goals and keepers.', 'High-zone reds drop into the red zone to receive unmarked; the receiver turns and plays a through ball behind or in front of the defence. White midfielders try to cut out passes; once the ball reaches the high zone or whites win it, everyone plays freely and whites counter.', 'Whites barred from the red zone; receiver in the red zone 2 touches and must pass within the area.', NULL, NULL, '11v11', 22, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Two-back build-up pattern with link players', 'passing_unopposed', 'unopposed', 'in_possession', 102, 102, 'Attacking Tactical Situation 11: Practice 1', 'FC Barcelona', 'Rehearse beating a high press in the first stage of build-up with two players at the back.', '30 x 30 yard square with cones and two mannequins in the middle; goalkeeper at the bottom, a holding midfielder (16), a No.10, a centre midfielder (8), a winger (7) and players on the far side.', 'Keeper plays to 16, who returns it and drops back to receive again on the half turn; 10 moves to get free, 8 heads for an open lane on the left, and a set chain of passes through 10, 8 and 7 brings the ball back to the keeper. Players rotate positions (8 to 7, 10 to 8, 7 to 10) and the next run goes to the right side.', NULL, NULL, 'Open body shape on the half turn to see the next pass; talk, move and look around constantly.', 'about 7 plus GK', 7, 9, '30 x 30 yards', 27.4, 27.4, NULL, false, true, true, NULL, 570),
  ('Link-player one-two passing square', 'passing_unopposed', 'unopposed', 'in_possession', 103, 103, 'Attacking Tactical Situation 11: Practice 2', 'FC Barcelona', 'Train the link player role used to play through pressure with two at the back.', '30 x 30 yard square, players on four corners (A-E) beside four mannequins, two link players in the centre.', 'A plays a one-two with B, then passes into a centre link player who sets the ball in front of a mannequin for B running round it; the same pattern continues with C and D using the other central player. Corner players rotate one position after each pass.', 'One touch.', NULL, 'Well-timed passes in front of runners so they keep their speed; link players open their body to pass at different angles and pass with the back foot.', '7 (5 corners + 2 link)', 7, 10, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 580),
  ('Keeper-to-cross build-up pattern', 'combination', 'unopposed', 'in_possession', 104, 104, 'Attacking Tactical Situation 11: Practice 3', 'FC Barcelona', 'Beat first-stage pressure in build-up and finish with a low cross.', '40 x 40 yard area with a goal and keeper at the top and a keeper at the bottom; mannequins as opponents, centre backs 5 and 2, midfielders 16, 8, 6, forward 10, winger 22.', 'The far keeper kicks long to the near keeper; 16 drops, 5 widens and 22 moves up together. Ball goes 16 to 5, 8 drops to receive and plays 22, who carries forward and crosses low for 10 to finish with 8 following in to the back post. Players switch and the pattern then runs down the right.', NULL, NULL, NULL, 'about 8 plus 2 GKs', 8, 12, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 590),
  ('4v4 plus 4 find the target player', 'possession', 'overload', 'in_possession', 105, 106, 'Attacking Tactical Situation 11: Practice 4', 'FC Barcelona', 'Find a specific unmarked player and switch the ball to the far side.', '30 x 30 yard square with a 4v4 inside and four neutral players on the outside; one player of the team in possession wears a yellow bib as the target.', 'A neutral dribbles in to make 5v4. The team must get the ball to the bibbed target, who then passes it to the opposite side for a point. The bib can be handed to a team-mate if he is man-marked. Defenders who win it take the bib and play for the same aim; the neutral goes back out once the aim is met.', 'Outside neutrals may be used to keep the ball but have one touch.', 'Variation: two bibs to make the target easier to find. Progression: time limit (e.g. 10 seconds) or possession switches over.', 'Open body shape and keep moving to create passing angles.', '4v4+4', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 600),
  ('8v6 free-player build-up end line game', 'phase_of_play', 'overload', 'in_possession', 107, 109, 'Attacking Tactical Situation 11: Practice 5', 'FC Barcelona', 'Break through first-stage pressure with two at the back by finding the free player.', 'Half a pitch with a goal and keeper; reds (8 incl. keeper) start on cones, 6 whites; halfway line is the end line, coach with balls on halfway.', 'Coach kicks long to the keeper, reds move into build-up positions (16 drops between the centre backs, who split wide) and try to pass to the free player and dribble over halfway without long balls. Whites win it and counter on the goal. Four worked examples show link players (6, 10, 8) and free players (8, 5, 3, 22) depending on where pressure comes from.', 'No long passes.', NULL, 'Read the situation quickly; with clever movement there is always a free man to find.', '8v6', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('11v11 build-up through pressure', 'conditioned_game', 'opposed', 'in_possession', 110, 110, 'Attacking Tactical Situation 11: Practice 6', 'FC Barcelona', 'Build up from the keeper with two at the back against an opposition press.', 'Full pitch, 11v11, white zone marked around the opposition centre backs.', 'Reds build from the keeper with two centre backs and no long passes; whites press to win the ball and counter.', 'Reds may not play long. White centre backs cannot leave their zone when defending, so 10 can drop into the main zone unmarked for an overload.', NULL, 'Read the situation fast, find the free man, synchronise movement, good body shape and well-weighted passes.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('8v6 three-back build-up end line game', 'phase_of_play', 'overload', 'in_possession', 113, 114, 'Attacking Tactical Situation 12: Practice', 'FC Barcelona', 'Break first-stage pressure in build-up using three players at the back.', 'Half pitch with goal and keeper; 8 reds on cones, 6 whites; halfway line is the end line, coach with balls.', 'Coach plays long to the keeper; the right back pushes into midfield, the other three defenders form a back trio and the holding midfielder drops a few yards as the usual free player. Reds pass to the free player and dribble over halfway; whites win it and counter. Three examples show 8, 3 and 22 becoming free, with 10 or 16 as link players.', 'No long balls.', NULL, NULL, '8v6', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Right-flank combination to shot (diamond)', 'combination', 'unopposed', 'in_possession', 117, 117, 'Attacking Tactical Situation 13: Practice 1', 'FC Barcelona', 'Rehearse the combinations used to attack down the right flank.', '40 x 40 yards split in two halves, each with a goal and keeper and mannequins; a diamond of centre back (3), 2, 6 and 17 in each half.', 'Centre back at the base passes left or right, gets it back and plays into the centre; the set combination ends with a shot on goal. Players rotate one position (3 to 2, 2 to 6, 6 to 17, 17 to the other half).', 'Start on two touches, then one.', 'Practice 2 is a variation with a different pattern.', 'Communicate, heads up, synchronised movement.', 'about 10 plus 2 GKs', 8, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 640),
  ('Right-flank combination to shot (variation)', 'combination', 'unopposed', 'in_possession', 118, 118, 'Attacking Tactical Situation 13: Practice 2', 'FC Barcelona', 'More combination play for attacking down the right flank.', 'Same 40 x 40 split area with goals, keepers and mannequins as Practice 1.', 'Centre back passes left, gets it back and switches to the other side; a different rehearsed combination finishes with a shot. Rotation 3 to 6, 6 to 2, 2 to 17, 17 to the other side on the left; 3 to 2, 2 to 6, 6 to 17 on the right.', NULL, NULL, NULL, 'about 10 plus 2 GKs', 8, 14, '40 x 40 yards', 36.6, 36.6, NULL, true, true, true, NULL, 650),
  ('4v4 plus 2 right-flank possession', 'positional_game', 'overload', 'in_possession', 119, 119, 'Attacking Tactical Situation 13: Practice 3', 'FC Barcelona', 'Develop build-up play down the right flank by position.', '30 x 30 yards; 4 reds (centre back, holding mid, right back, right winger) v 4 whites, with outside player 5 at one end with balls and 7 at the other.', 'Reds move the ball from 5 to 7 using at least two passes for a point, then turn to 5''s side for a new ball; they can play back to 5. Whites score by winning it and making 5-7 passes in a row. After 10 balls the teams swap.', 'Outside player 5 one touch or pass within 3 seconds.', 'Limit touches to suit the level.', NULL, '4v4+2', 10, 10, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 660),
  ('4v4 plus 4 right-flank attack to goal', 'small_sided_game', 'opposed', 'in_possession', 120, 120, 'Attacking Tactical Situation 13: Practice 4', 'FC Barcelona', 'Develop attacking play down the right flank ending in a shot.', 'Quarter of the pitch with a 30 x 30 yard area, 4v4 inside, each team with two outside players, goals and keepers at both ends.', 'Reds, helped by their outside players, try to dribble over the end line and shoot unopposed. If whites win it they pass to an outside player, then everyone can leave the area and it is 6v6 with 8 seconds to finish the counter.', 'Red outside players one touch; whites have 8 seconds on the counter.', 'Limit red touches to suit the level.', NULL, '4v4+4 plus 2 GKs', 14, 14, '30 x 30 yards in a quarter pitch', 27.4, 27.4, NULL, true, true, true, NULL, 670),
  ('11v11 with 4v3 flank zones', 'conditioned_game', 'overload', 'in_possession', 121, 121, 'Attacking Tactical Situation 13: Practice 5', 'FC Barcelona', 'Develop attacking play down the flanks using a numbers advantage.', '11v11 with two blue zones on the flanks up to a red line; inside each zone it is always 4 reds (centre back, full back, attacking mid, forward) v 3 whites (full back, centre back, holding mid).', 'Reds work the ball into the zones, use the overload to dribble or receive beyond the red line, then get into the box and score.', 'When whites have it there are no zone limits. Whites in the blue zone cannot defend beyond the red line. Offside applies.', 'Limit touches inside the blue zones.', NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('One-touch switching play diamond', 'passing_unopposed', 'unopposed', 'in_possession', 124, 124, 'Attacking Tactical Situation 14: Practice 1', 'FC Barcelona', 'Practise switching play with one-touch passing.', '25 x 25 yard square with four corner players and two central players who never turn with the ball.', 'Corner player passes to the nearest central player, who sets it back and moves to receive again; the next pass goes to the far central player, who plays to his partner, who finds the opposite corner. That corner then starts again towards the closest middle player.', 'One touch.', NULL, 'Keep moving and time runs; open body shape for the angle to play one touch.', '6', 6, 8, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 690),
  ('3v3 plus 3 switching play', 'possession', 'overload', 'in_possession', 125, 125, 'Attacking Tactical Situation 14: Practice 2', 'FC Barcelona', 'Practise switching play from one side to the other.', 'Two 15 x 25 yard areas running the same game; 3v3 in each with three neutrals (one at the top, one on each side).', 'Team in possession keeps it and switches from one side neutral to the other for a point, using the top neutral to help. They may pass back to the neutral they got it from.', 'Side neutrals can''t pass to each other. At least one pass between team-mates before a switch. Inside players two touches, neutrals one touch or 3 seconds.', NULL, 'Keep moving, quality passes, open body shape to see the next pass.', '3v3+3 (x2 grids)', 9, 18, '15 x 25 yards', 22.9, 13.7, NULL, false, false, true, NULL, 700),
  ('6v6 plus 4 switching dynamic game', 'positional_game', 'overload', 'in_possession', 126, 126, 'Attacking Tactical Situation 14: Practice 3', 'FC Barcelona', 'Practise switching play by position.', '30 x 40 yard area, 6v6 inside with four outside players (two at the top, one each side) for the team in possession; red end line at the bottom.', 'Reds move the ball from one side player to the other with help from the top players; 2-3 switches in a row score a point. Whites who win it try to dribble over the end line.', 'Reds inside two touches and at least two passes before switching; outside players can''t pass to each other and have one touch or 3 seconds.', NULL, 'Keep team balance and shape.', '6v6+4', 16, 16, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 710),
  ('11v11 strong side weak side switch game', 'conditioned_game', 'opposed', 'in_possession', 127, 127, 'Attacking Tactical Situation 14: Practice 4', 'FC Barcelona', 'Train switching play to the weak side before attacking the goal.', '11v11 with the pitch split lengthways into a strong and weak side, plus two touchline zones only for red full backs.', 'Each time a red full back in his zone receives, reds must switch the ball to the weak side before they are allowed to shoot.', 'Full backs in the zones two touches. Reds need at least one switch before shooting. No zone limits for whites.', NULL, 'Constant movement, well-timed weighted passes, open body shape, keep team balance.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 720),
  ('Long switch passing to blue target box', 'passing_unopposed', 'unopposed', 'in_possession', 130, 130, 'Attacking Tactical Situation 15: Practice 1', 'FC Barcelona', 'Practise switching play with accurate long passes.', '50 x 40 yard area run on both sides at once; players A, B, C, D, E on each side, a cone in the centre and a small blue target square near each far corner.', 'Coach throws a ball up; when it lands A plays C, who returns it, then A finds B who has checked away from the cone while C moves up. B plays C, who hits a long ball to the A on the other side arriving into the blue box; A passes to D, who drops, takes a touch and returns it to the start (E). Players rotate A to B, B to C and so on.', 'Size of the blue box set by player level.', NULL, 'Correct weight and accuracy on short and long passes; use any body part to control the lofted ball.', '10 (5 per side)', 10, 12, '50 x 40 yards', 45.7, 36.6, NULL, false, false, true, NULL, 730),
  ('4v2 zone-to-zone long switch game', 'possession', 'overload', 'in_possession', 131, 131, 'Attacking Tactical Situation 15: Practice 2', 'FC Barcelona', 'Practise switching play with long passes under pressure.', '45 x 20 yards with two 15 x 20 side zones; 3 teams of 6. 4v2 in each side zone with 2 red outside helpers per zone, and 4 red target players in small zones beside the playing areas.', 'The 4 complete at least 3 passes, then hit an accurate long ball to the red targets on the other side; a target then plays a new ball in. The 2 defenders try to win the ball and keep it as long as possible. Most switches in 3 minutes wins.', 'Switch only counts if controlled inside the target area. Teams of 4 two touches, outside players one touch.', NULL, NULL, '18 (3 teams of 6)', 18, 18, '45 x 20 yards', 41.1, 18.3, 3.0, false, false, true, NULL, 740),
  ('8v8 split pitch long switch to full backs', 'small_sided_game', 'opposed', 'in_possession', 132, 132, 'Attacking Tactical Situation 15: Practice 3', 'FC Barcelona', 'Practise switching play with long passes to the weak-side full back.', '8v8 in an area split lengthways in two, with two blue touchline zones only red full backs may enter; red holding and centre mids in yellow bibs can use both halves.', 'Keeper starts to one side; reds make at least 2 passes, then play long to the far blue zone, after which they attack the goal freely. The weak-side full back waits in the zone for the switch and steps out once he has passed on. Whites who win it can go anywhere; if reds regain it they go back to the keeper and restart.', 'Full backs in the zones two touches; reds must switch each time they have the ball.', NULL, 'Correct support positions and distances; the switch pass must be accurate and played for the full back to run on to.', '8v8', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 750),
  ('11v11 three-lane switch for 2v1s', 'conditioned_game', 'overload', 'in_possession', 133, 133, 'Attacking Tactical Situation 15: Practice 4', 'FC Barcelona', 'Switch play with long balls to exploit a 2v1 on the far flank.', '11v11 on two-thirds of the pitch, divided into three lanes (two side zones and the centre).', 'When reds have the ball in one side zone, whites may keep only one player in the opposite side zone until the ball leaves the first area. Reds switch quickly with a long ball to use the 2v1 and score; if it doesn''t work they look for another way.', 'At least one switch each possession. No zone limits once whites win it.', NULL, 'Quick switches, fast combinations to use flank overloads, watch long-pass accuracy.', '11v11', 22, 22, 'two-thirds of the pitch', NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Winger and No.10 final-third combinations', 'combination', 'unopposed', 'in_possession', 136, 136, 'Attacking Tactical Situation 16: Practice 1', 'FC Barcelona', 'Rehearse third-stage combinations between winger and attacking midfielder.', '50 x 40 yards split in two, each half with a goal, keeper, mannequins and cones; players A (holding mid), B and C.', 'Left: A plays C (attacking mid) who checks off a cone, C sets it back, A finds winger B dropping off to turn; C runs past for a one-two and B shoots. Right: A plays winger C who sets back, A finds B (attacking mid) dropping to turn, who plays a diagonal for C to shoot. Rotate A to B, B to C, C to the other half.', NULL, NULL, NULL, '6+ plus 2 GKs', 6, 12, '50 x 40 yards', 45.7, 36.6, NULL, true, true, true, NULL, 770),
  ('3v2 zonal winger-No.10 decision finishing', 'finishing', 'passive', 'in_possession', 137, 137, 'Attacking Tactical Situation 16: Practice 2', 'FC Barcelona', 'Make the right choice between through pass and dribble in the final third.', 'Half a pitch with two goals and keepers; in each half a blue zone with two mannequins and 2 passive defenders, red cone gate below, centre backs 5 and 3 with balls, centre mids 16 and 6.', 'Centre back plays the centre mid, who carries through the cones and passes to the winger or attacking mid dropping behind the mannequins to turn. If defenders drop to stop the through ball, the man on the ball dribbles into the space and shoots.', 'Defenders passive: don''t follow deep runs, can''t leave the blue area.', NULL, 'Read the situation; final pass timed and weighted for the run; accurate finishing.', '3v2 per half plus GKs', 10, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 780),
  ('Winger-No.10 overlap combinations to cross', 'combination', 'unopposed', 'in_possession', 140, 140, 'Attacking Tactical Situation 17: Practice 1', 'FC Barcelona', 'Rehearse combinations that create a 2v1 on the flank.', '50 x 40 yards split in two with goals, keepers and mannequins; players A (holding mid), B and C.', 'Left: A plays winger C who sets back, A finds attacking mid B coming to the ball; B plays C and overlaps, C dribbles in, plays B and attacks the low cross to score. Right: A plays C who sets back, B receives and turns, finds C and runs diagonally behind the mannequin; C returns it and gets in for the low cross. Rotate A to B, B to C, C to the other side.', NULL, NULL, NULL, '6+ plus 2 GKs', 6, 12, '50 x 40 yards', 45.7, 36.6, NULL, true, true, true, NULL, 790),
  ('3v2 zonal flank overload finishing', 'finishing', 'passive', 'in_possession', 141, 141, 'Attacking Tactical Situation 17: Practice 2', 'FC Barcelona', 'Use synchronised winger-No.10 combinations to create a flank overload and score.', 'Same half-pitch set-up as Situation 16 Practice 2: two goals, blue zones with mannequins, 2 passive defenders per side, cone gates, centre backs with balls.', 'Centre back plays the centre mid, who carries through the cones and passes to the attacking mid moving behind the mannequins; the two reds combine to overload the flank and finish. Defenders track the attacking mid, opening space inside for the winger.', 'Defenders passive and can''t go beyond the blue area.', NULL, 'Receive on the half turn; overlap starts as soon as the pass is made; shot accuracy over power.', '2v2+2 per half plus GKs', 10, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 800),
  ('One-two, attack free space, cross', 'combination', 'unopposed', 'in_possession', 144, 144, 'Attacking Tactical Situation 18: Practice 1', 'FC Barcelona', 'Rehearse creating space with one player''s drop and attacking it with another.', 'Two halves with goals, keepers and mannequins; A (holding mid), B (attacking mid) and C (winger).', 'Left: A plays B, who checks off, B sets back; winger C drops to clear the flank, B runs into it, takes A''s pass and crosses low for C to finish. Right: A plays C, who sets back; B drops to empty the centre and C runs in behind the mannequin for a long ball and shoots. Rotate A to B, B to C, C to the other side.', NULL, NULL, NULL, '6+ plus 2 GKs', 6, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 810),
  ('3v2 zone create and attack free space', 'finishing', 'passive', 'in_possession', 145, 145, 'Attacking Tactical Situation 18: Practice 2', 'FC Barcelona', 'Create space with a drop and attack it with a forward run.', 'Half pitch with two goals; in each half a blue zone with mannequins and 2 defenders who follow the forwards'' movements, red cone gates, centre backs with balls.', 'Holding mid takes it from the centre back, carries through the cones and passes into the space opened by the winger or attacking mid; the two reds attack the gap and score.', 'Defenders passive and can''t follow beyond the blue area.', NULL, 'As one drops the other goes forward; quality weighted passes and accurate finishing.', '3v2 per half plus GKs', 10, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 820),
  ('5v4 plus 1 three-zone combination game', 'small_sided_game', 'overload', 'in_possession', 146, 146, 'Attacking Tactical Situation 18: Practice 3', 'FC Barcelona', 'Wingers and attacking mids pick the right combination to break the defence.', 'Two games on half a pitch, each with three areas: a white build-up area (3+1 v 2), a blue area (2v2) and a red end zone before goal; balls with the outside player.', 'Reds in the white area pass into the two in the blue area, who combine to dribble over the red line or receive beyond it (offside on) and score. Any of the six situations analysed can be used. If whites win it they dribble over the red end line and all zones open; if reds regain it they go back to the outside player.', 'Players stay in their areas. Reds in white area two touches, outside player one. Whites can''t enter the red area.', NULL, 'Keep team balance; read the situation, stay mobile, move in sync.', '5v4+1', 10, 20, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 830),
  ('Overload the side pattern with overlap', 'combination', 'unopposed', 'in_possession', 149, 149, 'Attacking Tactical Situation 19: Practice 1', 'FC Barcelona', 'Rehearse third-stage combinations after overloading one side.', 'Two halves with goals, keepers and mannequins; A (holding mid), B (attacking mid), C (winger), D (extra player arriving to overload).', 'Left: A plays C who sets back, B drops, turns, finds C and overlaps; C dribbles in and either plays B or combines with D. Right: A plays B who sets back, C drops and dribbles inside while B makes a third-man run into space; the move ends with B via D. Rotate A to B, B to C, C to D, D to the other side.', NULL, NULL, NULL, '8+ plus 2 GKs', 8, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 840),
  ('3v2 zonal overload the side finishing', 'finishing', 'passive', 'in_possession', 150, 150, 'Attacking Tactical Situation 19: Practice 2', 'FC Barcelona', 'Overload one side with a late extra attacker and finish.', 'Half pitch with two goals, blue zones with mannequins and 2 passive defenders each; two extra attacking mids wait on the blue cone; centre backs with balls, holding mids at the cone gates.', 'Centre back plays the holding mid, who carries through the cones and passes to the winger or attacking mid; the second attacking mid enters at the right moment to overload the side and the reds break through and score.', 'Defenders passive and can''t leave the blue area.', NULL, 'When one drops, the other moves into a passing lane; first receiver in the blue area takes it on the half turn.', '3v2 per half plus GKs', 12, 16, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 850),
  ('6v4+1 three-zone wing combination game', 'phase_of_play', 'overload', 'in_possession', 151, 151, 'Attacking Tactical Situation 19: Practice 3', 'FC Barcelona', 'Wingers and attacking midfielders combine to break through the defence in the final third.', 'Two side-by-side areas, each with a low white zone, a blue middle zone and a red end zone with a goal and keeper; 3(+1) v 2 in the white zone and 2v2 in the blue zone, plus two red midfielders outside who may enter the blue zone.', 'Reds build in the white zone and pass into the blue zone, where the forwards and the entering midfielder combine to dribble across the red line or receive beyond it and score. If whites win it they try to dribble out over the end line and all may move freely; reds restart via the outside player.', 'White-zone reds 2 touches, outside player 1 touch; whites stay in their zones until they win the ball.', NULL, 'Open body shape on the half turn to see the next pass; keep team balance.', '6v4 (+1) per side', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 860),
  ('Winger and attacking mid combination final game', 'conditioned_game', 'opposed', 'in_possession', 152, 152, 'Attacking Tactical Situation 19: Practice 4', 'FC Barcelona', 'Wingers, attacking midfielders and full backs use rehearsed combinations to break through and score.', '11v11 with pitch split left/right; low zone, a blue middle band for 3 opposing midfielders, and a high zone with 2v2 on each side.', 'Reds play 3v2 or 3v1 per side in the low zone and look to find teammates in the high zone; once the ball goes in, one player may cross over to the strong side to make 3v2. Whites counter attack freely if they win it.', 'Only the white striker and red attacking midfielders cross halves; only the 4 forwards and 4 white defenders may enter the box; blue-zone midfielders stay in their band.', NULL, 'Show all the combinations practised in the session.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 870),
  ('Create space, receive, turn, cross pattern', 'combination', 'unopposed', 'in_possession', 155, 155, 'Attacking Tactical Situation 20: Practice 1', 'FC Barcelona', 'Rehearse winger, attacking midfielder and full back combinations to attack free space on the flank.', '50 x 40 yards split into two halves, each with a goal and keeper and a small blue square in the middle; players A (holding mid), C (winger), D (attacking mid), B (full back).', 'Left: A passes to C who checks up and back to make room for the full back, C turns in the square and feeds D, D slips B into the flank space and B crosses low for D to finish. Right: C turns in the square and plays B directly, who crosses for D. Players rotate A to B to C to D.', NULL, NULL, 'Directional first touch in the square; timing and synchronised movement.', NULL, NULL, NULL, '50 x 40 yards', 45.7, 36.6, NULL, true, true, true, NULL, 880),
  ('Attacking flank free space with passive defenders', 'combination', 'passive', 'in_possession', 156, 156, 'Attacking Tactical Situation 20: Practice 2', 'FC Barcelona', 'Third-stage combination play attacking space created on the flank.', 'Two side-by-side zones with mannequins in the blue area, a red end area with goal and keeper, cones for centre midfielders to pass through; 2 passive white defenders.', 'Centre backs feed the centre midfielders, who carry through the red cones and pass to the winger dropping behind the mannequin; the white full back follows the winger, opening space, and the winger, full back and attacking mid attack it and finish.', 'White defenders may not enter the red area; they follow the forwards as they drop.', NULL, 'Read the situation and synchronise movements; quality turning, passing and finishing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 890),
  ('5v4+1 three-zone flank combination game', 'phase_of_play', 'overload', 'in_possession', 157, 157, 'Attacking Tactical Situation 20: Practice 3', 'FC Barcelona', 'Wingers, attacking midfielders and full backs combine to break through.', 'Same 3-zone, two-sided set-up as the earlier 6v4+1 game (white, blue, red zones with goals and keepers).', 'As the earlier version, but the red full backs may now enter the blue area to exploit the space created by the winger''s movement.', NULL, NULL, 'Open up and receive/pass with the back foot; always keep team balance.', '5v4 (+1) per side', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 900),
  ('Wingers, mid and full backs final game', 'conditioned_game', 'opposed', 'in_possession', 158, 158, 'Attacking Tactical Situation 20: Practice 4', 'FC Barcelona', 'Use flank combinations involving full backs to break through and score.', '11v11 split left/right with low zone, blue midfield band (3 white midfielders) and high zone with 2v2 per side.', 'Reds play 3v2/3v1 in the low zone and find forwards in the high zone; red full backs may run into the high zone to make 3v2 and attack the free space. Whites counter freely if they win it.', 'Only the white striker crosses halves; blue-band midfielders stay in their band.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 910),
  ('Passing pattern: 2 centre backs keep balance', 'passing_unopposed', 'unopposed', 'in_possession', 161, 161, 'Attacking Tactical Situation 21: Practice 1', 'FC Barcelona', 'Keep balance at the back with a 2-man defence when a centre back steps forward.', '25 x 25 yards with 2 centre backs, 1 holding mid, 1 centre mid and 2 wingers on cones.', 'CB 5 plays to the holding mid 16 and back to CB 3, who dribbles forward while 16 drops into his spot and 6 drops into 16''s spot; ball goes to the winger dropping, inside to 6, out to the other winger, back to 5 and across to 3, who returns to his start. Repeat to the other side with 5 stepping up.', NULL, NULL, 'Accurate weight of pass; rhythm and timing of runs; communicate, heads up.', '6 players', 6, 6, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 920),
  ('Covering the centre back''s forward run 3v1', 'transition', 'overload', 'in_possession', 162, 162, 'Attacking Tactical Situation 21: Practice 2', 'FC Barcelona', 'Keep balance at the back with a 2-man defence and react to a new attack.', '25 x 25 yards; keeper and goal at one end, two mini goals behind two white end zones at the other; 2 red CBs and holding mid v 1 white forward (passive); coach with balls.', 'Keeper plays a CB, reds beat the passive forward and one dribbles into a white zone to shoot at a mini goal while the holding mid fills the vacated spot. On the shot the coach feeds a new ball to the white player and reds must stop him scoring.', NULL, NULL, 'Stay alert to react quickly to changing situations.', '3v1 + GK', 5, 5, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 930),
  ('Balance at back two-zone game (2 CBs)', 'small_sided_game', 'opposed', 'in_possession', 163, 163, 'Attacking Tactical Situation 21: Practice 3', 'FC Barcelona', 'Keep balance at the back with a 2-man defence and win the ball back fast.', '25 x 25 yards in two zones with a goal and keeper at each end; 3v1 for reds in the low zone, 3v4 in the high zone.', 'One red defender dribbles into the high zone to make 4v4 while the holding mid covers his place to keep 2v1 behind. If whites win it, all move freely and reds try to regain and recycle to their keeper.', 'Only one red defender may step up at a time; out of play restarts with the red keeper.', NULL, 'Exploit the overload at the back; win the ball back as fast as possible.', '7v5 + 2 GKs', NULL, NULL, '25 x 25 yards', 22.9, 22.9, NULL, true, true, true, NULL, 940),
  ('Balance at back build-up 11v11 (2 CBs)', 'conditioned_game', 'opposed', 'in_possession', 164, 164, 'Attacking Tactical Situation 21: Practice 4', 'FC Barcelona', 'Keep balance at the back with a 2-man defence during build-up.', '11v11 with a blue low zone (3v1 for reds) and a high zone (7v9).', 'A red defender dribbles into the high zone to make 8v9 and attack; the holding mid drops to keep the low-zone overload for a fast regain. Whites who win it go to their striker in the blue zone and all move freely; reds who regain go back to their keeper.', 'Only one red may step into the high zone; whites stay out of the blue zone unless they win the ball.', NULL, NULL, '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 950),
  ('Passing pattern: 3-man defence keeps balance', 'passing_unopposed', 'unopposed', 'in_possession', 167, 167, 'Attacking Tactical Situation 22: Practice 1', 'FC Barcelona', 'Keep balance at the back with a 3-man defence when a centre back steps forward.', '30 x 30 yards with 3 defenders, holding mid, centre mid and 2 wingers on cones.', '22 plays 16 to 5 to 3; 3 carries forward while 16 drops into his spot and 6 drops behind; ball goes winger, 6, other winger and back across the back line as 3 returns and 16 recovers. Repeat to the other side with 22 stepping up.', NULL, NULL, 'Cover and step up again at the right moment; accurate weighted passes and communication.', '7 players', 7, 7, '30 x 30 yards', 27.4, 27.4, NULL, false, false, false, NULL, 960),
  ('Covering the centre back''s run 4v2', 'transition', 'overload', 'in_possession', 168, 168, 'Attacking Tactical Situation 22: Practice 2', 'FC Barcelona', 'Keep balance at the back with a 3-man defence.', '35 x 35 yards; keeper and goal at one end, two white end zones with mini goals at the other; 3 red defenders and holding mid v 2 white forwards (passive); coach with balls.', 'Reds beat the passive press and one defender dribbles into a white zone to score a mini goal while 16 fills in. On the shot the coach plays a new ball to the 2 whites and reds must defend the 3v2.', NULL, NULL, 'With the overload a man should be free to receive and step forward; react quickly.', '4v2 + GK', 7, 7, '35 x 35 yards', 32.0, 32.0, NULL, true, true, true, NULL, 970),
  ('Balance at back two-zone game (3 CBs)', 'small_sided_game', 'opposed', 'in_possession', 169, 169, 'Attacking Tactical Situation 22: Practice 3', 'FC Barcelona', 'Keep balance at the back with a 3-man defence.', '35 x 45 yards in two zones with goals and keepers; 4v2 in the low zone, 3v4 in the high zone.', 'One red defender dribbles up to make 4v4 while 16 covers to keep 3v2 behind; whites try to win it and score, then all move freely; reds regain and recycle to their keeper.', 'One defender up at a time; out of play restarts with the red keeper.', NULL, NULL, '8v6 + 2 GKs', NULL, NULL, '35 x 45 yards', 32.0, 41.1, NULL, true, true, true, NULL, 980),
  ('Balance at back build-up 11v11 (3 CBs)', 'conditioned_game', 'opposed', 'in_possession', 170, 170, 'Attacking Tactical Situation 22: Practice 4', 'FC Barcelona', 'Keep balance at the back with a 3-man defence during build-up.', '11v11 with low zone 4v2 and high zone 6v8.', 'A red defender carries into the high zone to create an overload while 16 keeps balance behind. Whites who win it hit their forwards in the blue zone and play freely; reds regain and go back to their keeper.', 'Only one red defender enters the high zone; whites stay out of the low zone unless they win the ball.', NULL, 'High tempo combinations; always keep a back-line overload for the negative transition.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 990),
  ('4v4+4 possession with 3v2 back zone', 'possession', 'opposed', 'in_possession', 173, 173, 'Attacking Tactical Situation 23: Practice 1', 'FC Barcelona', 'Keep an overload at the back while attacking, ready for the negative transition.', '30 x 40 yards: large white zone 4v4 with 2 outside players per team, plus a blue back zone 3v2 (2 CBs and holding mid v 2 forwards).', 'Reds aim for 12-15 passes using outsiders and the blue zone, always keeping the blue-zone overload. Whites who win it look to dribble out over the blue end line. Holding mid 16 shifts to keep equality up top and superiority behind.', 'Outside players 1 touch; all move freely once whites win the ball.', NULL, 'If a white forward moves up, 16 tracks him; if both do, 16 and a CB go too.', '4v4 + 3v2 + 4 outside', 17, 17, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 1000),
  ('Two-zone negative transition 11v11', 'conditioned_game', 'opposed', 'to_defend', 174, 175, 'Attacking Tactical Situation 23: Practice 2', 'FC Barcelona', 'Keep balance and a back overload, ready to react on losing the ball.', '11v11 with a blue back zone (2 red CBs and holding mid v 2 white forwards) and a line behind it; red keeper acts as an extra outfield support.', 'Reds attack while 16 keeps the overload; after a red shot restart with the red keeper. Whites who win it go to their forwards in the blue zone to dribble over the end line, while reds react to win it back.', 'All move freely only once whites win possession.', 'Variation (p175, Practice 3): normal 11v11, whites counter after winning it; 16 keeps 3v2 or 2v1 in the blue zone and may sit higher against a 4-2-3-1.', 'Read the situation, keep balance at the back; react fast after losing it; communicate.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 1010),
  ('Full back''s timing in 3-zone game', 'positional_game', 'opposed', 'in_possession', 178, 178, 'Attacking Tactical Situation 24: Practice 1', 'FC Barcelona', 'Full backs learn the right moment to push forward while keeping balance.', '5v5 in a 35 x 35 yard area with two 5 x 30 yard side zones for the red full backs; 2 gates on the end line, coach with balls, white players on blue cones.', 'Reds keep the ball with full backs joining when possession is secure while the attacking mid covers, then the full backs recover quickly. Whites who win it get help from the two cone players and try to dribble through a gate.', 'Full backs 1 touch or pass within 3 seconds; both white helpers may enter at once; red full backs come inside to defend; reds regain and pass to the coach.', NULL, 'Well-timed forward runs; quick reactions to a negative transition.', '5v5 + 2 full backs + 2 white helpers', NULL, NULL, '35 x 35 yards', 32.0, 32.0, NULL, true, false, true, NULL, 1020),
  ('Full back runs 8v8 half pitch', 'conditioned_game', 'opposed', 'in_possession', 179, 179, 'Attacking Tactical Situation 24: Practice 2', 'FC Barcelona', 'Full backs time forward runs without leaving the team unbalanced.', '8v8 in half a pitch; one big goal and keeper, 3 small goals for the whites behind a red zone.', 'Red full backs push on at the right moment while attacking mids cover; on losing the ball reds press high. Whites counter to score in a small goal.', 'Whites must shoot from inside the red zone.', NULL, 'Synchronised winger/full back moves; cover teammates who go forward; win it high to stop whites reaching the red zone.', '8v8 + GK', 17, 17, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 1030),
  ('Full back runs 11v11 two-thirds pitch', 'conditioned_game', 'opposed', 'in_possession', 180, 180, 'Attacking Tactical Situation 24: Practice 3', 'FC Barcelona', 'Full backs time forward runs while midfielders cover.', '11v11 on two-thirds of a pitch with a red end area on the flank side.', 'Red full backs wait and then enter the red area to create 4v4 inside it and 2v1 wide; attacking mids drop into cover. Whites counter with no restrictions once they win it.', 'Only red full backs may enter the red area; white midfielders and forwards may not.', NULL, NULL, '11v11', 22, 22, 'two-thirds pitch', NULL, NULL, NULL, true, true, true, NULL, 1040),
  ('4v4+4 quick reaction negative transition', 'transition', 'overload', 'to_defend', 183, 183, 'Attacking Tactical Situation 25: Practice 1', 'FC Barcelona', 'Quick reactions to win the ball back after losing it.', '30 x 30 yards, 4v4 inside with 4 red outside players, one per side.', 'Reds keep the ball with outside help (optionally a pass target for a point); whites win it and try to dribble over any side. On losing it, the outside players step in and help regain before whites get out.', 'Inside reds 2 touches, outside reds 1 touch.', NULL, 'Stay alert and react instantly to losing possession.', '4v4 (+4)', 12, 12, '30 x 30 yards', 27.4, 27.4, NULL, false, false, true, NULL, 1050),
  ('5v5+2 quick break attack game', 'transition', 'overload', 'to_defend', 184, 184, 'Attacking Tactical Situation 25: Practice 2', 'FC Barcelona', 'Quick reactions in the negative transition.', '40 x 40 yards, 5v5 with 2 red outside players.', 'Reds keep the ball with outsiders and try to dribble over the end line. On losing it, one outsider comes in to help win it back within 5 seconds, then plays to the other outsider. Whites score by keeping it 5+ seconds (1 point) or dribbling over the end line (3 points).', 'Only one outsider enters; outsiders 1 touch; out of play restarts with the outsiders.', NULL, NULL, '5v5 (+2)', 12, 12, '40 x 40 yards', 36.6, 36.6, NULL, false, false, true, NULL, 1060),
  ('5v5+2 quick break finishing game', 'transition', 'overload', 'to_defend', 185, 185, 'Attacking Tactical Situation 25: Practice 3', 'FC Barcelona', 'Quick reactions in the negative transition with a finish.', '40 x 40 yards, 5v6 with 2 red outside players, plus a 40 x 18 yard end zone with goal and keeper; coach with balls.', 'Reds dribble over the end line and score in the end zone; on losing it the outsiders come in to win it within 5 seconds. Whites dribble out the opposite end or keep the ball 5+ seconds.', 'Whites may not follow into the end zone; out of play the coach feeds the reds.', NULL, 'Always a safety player; keep team balance.', '5v6 (+2) + GK', NULL, NULL, '40 x 40 yards + 40 x 18 end zone', 36.6, 36.6, NULL, true, true, true, NULL, 1070),
  ('Two-phase negative transition 11v11', 'conditioned_game', 'opposed', 'to_defend', 186, 186, 'Attacking Tactical Situation 25: Practice 4', 'FC Barcelona', 'Quick reactions to regain the ball after losing it.', '11v11 on two-thirds of a pitch.', 'Phase 1: reds rehearse build-up patterns against passive whites, then deliberately give the ball to a white; it becomes live and reds must regain within 5 seconds while whites try to score (5-10 minutes). Phase 2: normal game, reds aim to regain within 5 seconds of every loss.', '5-second regain target.', NULL, 'Quick reactions; always a safety player; keep balance.', '11v11', 22, 22, 'two-thirds pitch', NULL, NULL, NULL, true, true, true, NULL, 1080),
  ('Win wide, attack flank: 3-zone game', 'transition', 'opposed', 'to_attack', 190, 190, 'Attacking Tactical Situation 26: Situation 1 (3 Zone Game)', 'FC Barcelona', 'Win the ball near the sideline and attack down that flank.', '6v6 plus a neutral target player; two 12 x 30 yard white side zones for full backs and wingers (red holding mid may also enter) and a 6 x 30 middle zone; coach with balls.', 'Coach feeds white 5, who tries to find the green target for a point. Reds press, steer play wide and win it with a 3v2 overload, then attack through that same side to dribble over the red end line or receive beyond it; red 10 offers a support option.', 'Offside applies.', NULL, 'Use the wide overload to cut passing lines; give options at once on winning it and attack the free space.', '6v6 (+1)', 13, 13, NULL, NULL, NULL, NULL, false, false, true, NULL, 1090),
  ('Win wide, attack flank: 4-zone game', 'transition', 'opposed', 'to_attack', 191, 191, 'Attacking Tactical Situation 26: Situation 1 (4 Zone Game)', 'FC Barcelona', 'Win the ball near the sideline and attack down the flank to a finish.', 'As the 3-zone game plus an end zone and two goalkeepers.', 'The white keeper starts to the full backs in the side zones; whites try to score past the far keeper. Reds make a 3v2 to win it and attack the same side, dribbling over or receiving beyond the red line then shooting unopposed.', 'Reds have 6-8 seconds to get into the end zone; out of play restarts with the white keeper.', NULL, NULL, '6v6 (+1) + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1100),
  ('Win wide, attack centre: 3-zone game', 'transition', 'opposed', 'to_attack', 192, 192, 'Attacking Tactical Situation 26: Situation 2 (3 Zone Game)', 'FC Barcelona', 'Win the ball near the sideline and switch play through the centre.', '45 x 45 yards, 8v7; two 10 x 45 side zones for full backs and wingers (2v2), two green target players in the middle; coach with balls.', 'Coach feeds white 5; whites try to find a target (if the ball goes wide they need 2 passes before coming back inside). Reds block targets, force play wide and regain; middle players then give options to switch and attack.', 'Reds have 6-8 seconds; dribble/receive over the red line = 2 points, blue line on opposite side = 1 point; offside applies.', NULL, NULL, '8v7', 15, 15, '45 x 45 yards', 41.1, 41.1, NULL, false, false, true, NULL, 1110),
  ('Win wide, attack centre: 4-zone game', 'transition', 'opposed', 'to_attack', 193, 193, 'Attacking Tactical Situation 26: Situation 2 (4 Zone Game)', 'FC Barcelona', 'Win the ball near the sideline and switch play to finish.', 'As the 3-zone version plus an end zone and two goalkeepers.', 'White keeper starts; whites score by finding a target (1 point), double if the target scores. Reds block, force wide, regain and get into the end zone to score unopposed.', '6-8 seconds; offside applies; a goal after dribbling the red line counts double; out of play restarts with the white keeper.', NULL, NULL, '8v7 + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1120),
  ('Win central, attack centre: 3-zone game', 'transition', 'opposed', 'to_attack', 194, 194, 'Attacking Tactical Situation 26: Situation 3 (3 Zone Game)', 'FC Barcelona', 'Win the ball in the centre and attack quickly.', '35 x 45 yards, 5v5 plus 3 extra reds outside: 2 wingers in 5 x 5 side boxes and a 10; coach with balls.', 'Coach feeds a white player, who tries to dribble or receive beyond the red line. When reds win it, 10 drops in as an option and the wingers make diagonal runs to receive beyond the far red line.', '6-8 seconds to score; offside applies; red 10 may receive but not dribble over the end line.', NULL, 'Quick support angles on winning it; well-timed runs into free space.', '5v5 (+3)', 13, 13, '35 x 45 yards', 32.0, 41.1, NULL, false, false, true, NULL, 1130),
  ('Win central, attack centre: 4-zone game', 'transition', 'opposed', 'to_attack', 195, 195, 'Attacking Tactical Situation 26: Situation 3 (4 Zone Game)', 'FC Barcelona', 'Win the ball in the centre and attack to a finish.', 'As the 3-zone version plus an end zone and two goalkeepers.', 'White keeper starts; same rules. Once reds get over the red line they shoot past the keeper unopposed.', '6-8 seconds; out of play restarts with the white keeper.', NULL, NULL, '5v5 (+3) + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1140),
  ('Win central, attack flank: 5-zone game', 'transition', 'opposed', 'to_attack', 196, 196, 'Attacking Tactical Situation 26: Situation 4 (5 Zone Game)', 'FC Barcelona', 'Win the ball in the centre and attack down the flanks.', '45 x 35 yards in 3 zones: central 25 x 25 with 5v6, white side zones, and 5 x 5 yellow boxes where red full backs start; coach with balls.', 'Coach feeds a white, who tries to dribble or receive over the end red line. When reds win it the full backs sprint into the side zones to make a wide overload, with 10 as a support option, and reds try to get over the red line on the flank.', '6-8 seconds; offside applies; only red full backs enter the side zones.', NULL, 'Quick support angles; well-timed runs into free space.', '5v6 (+2 full backs)', 13, 13, '45 x 35 yards', 41.1, 32.0, NULL, false, false, true, NULL, 1150),
  ('Win central, attack flank: 4-zone game', 'transition', 'opposed', 'to_attack', 197, 197, 'Attacking Tactical Situation 26: Situation 4 (4 Zone Game)', 'FC Barcelona', 'Win the ball in the centre and attack down the flanks to a finish.', 'As the 5-zone version plus an end zone and two goalkeepers.', 'White keeper starts via a centre back and whites try to score. When reds win it the full backs leave their cones to attack the flank, aiming to get over the red line within 6-8 seconds and shoot unopposed.', 'Only red full backs enter the side zones; out of play restarts with the white keeper.', NULL, NULL, '5v6 (+2) + 2 GKs', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1160),
  ('Positive transition 11v11 with side zones', 'conditioned_game', 'opposed', 'to_attack', 198, 198, 'Attacking Tactical Situation 26: Positive Transition Game with 2 Side Zones', 'FC Barcelona', 'Win the ball and counter attack quickly.', '11v11 with two marked side zones (blue) along the flanks.', 'Whites build up from the back (no long balls) to score. Reds press, and once they win it must finish a counter attack within 8 seconds; the side zones help them read where to take the ball.', 'No long passes for whites; 8-second counter limit; out of play restarts with the white keeper.', NULL, 'High tempo, accurate passing, communication and quick finishing; read the situation and attack free space.', '11v11', 22, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 1170),
  ('Midfield and forward chain shift in side zones', 'defending', 'passive', 'out_of_possession', 202, 202, 'Defending Tactical Situation 1: Practice 1', 'Guardiola (Barcelona)', 'Midfielders and forwards shift together as one block to stay compact and build a strong side.', 'Half pitch with two marked side zones; the white back line plus keeper sit on blue cones, the red midfield and forward line in front of them.', 'Whites move the ball across the back and keeper, holding it 5 seconds on each receipt so reds can slide over. When the ball enters a side zone the reds all move to that side and leave the far side zone empty.', 'Whites hold each pass 5 seconds; reds do not try to win the ball.', NULL, 'Striker angles his body to cut off the switch; keep distances short between pressers.', 'Whites back 4 + GK v red midfield and forward unit', NULL, NULL, 'Half pitch', NULL, NULL, NULL, false, true, false, NULL, 1180),
  ('Compact pressing 6v6+GK to three mini goals', 'defending', 'opposed', 'out_of_possession', 203, 203, 'Defending Tactical Situation 1: Practice 2', 'Guardiola (Barcelona)', 'Keep the pressing line cohesive and compact while shifting to the ball side.', 'Two side zones and a full-width middle zone; whites (6 + keeper) attack three mini goals, reds defend in front of them with a keeper behind on the other side.', 'Whites must shoot at a mini goal from inside the middle zone; when they pass into a side zone the whole red unit shifts across and leaves the weak side zone empty. Reds who win it get up to 4 passes to score past the keeper.', 'Ground passes only; whites shoot only from inside the middle zone; reds max 4 passes on the break.', NULL, 'Short distances between pressers; deny time and space; block forward passes.', '6v6 (+1 GK)', 13, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 1190),
  ('8v7 cohesive shift to press near the sideline', 'defending', 'opposed', 'out_of_possession', 204, 204, 'Defending Tactical Situation 1: Practice 3', 'Guardiola (Barcelona)', 'Slide across together to press near the touchline and leave the weak side empty.', '8v7 game with two side zones; whites build from their keeper towards a goal, reds defend and counter to the other goal.', 'Whites start from the keeper and try to score. When the ball goes into a side zone the reds must have vacated the far side zone within 3 seconds or whites get a point. Reds who win the ball counter with up to 4 passes.', 'Ground passes only; 3 second rule to empty weak side; reds max 4 passes.', NULL, 'Block forward passes; striker shapes to stop the switch; wingers track overlapping full backs.', '8v7', 15, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 1200),
  ('Back four and holding midfielder synchronised shift', 'defending', 'passive', 'out_of_possession', 207, 207, 'Defending Tactical Situation 2: Practice 1', 'Guardiola (Barcelona)', 'Back four and defensive midfielder react together to press the ball and stay compact with an extra man at the back.', 'Half pitch with a blue band holding the red back four; red holding midfielder just in front; two white midfielders and two white full backs on yellow cones, a coach with balls in the centre.', 'Coach feeds a white midfielder who dribbles towards a touchline while the back line slides. Once he passes to the full back, the near red full back steps out to press and the No.6 drops in to cover the gap; ball goes back to the coach and all reset. Phase two: centre backs leave gaps for the No.6 to fill; phase three: No.6 starts higher and defenders use offside.', NULL, NULL, 'Short distances and synchronised movement; full back presses at the right moment so the opponent cannot scan.', '4+1 defenders v 4 whites + coach', 9, 10, 'Half pitch', NULL, NULL, NULL, false, true, false, NULL, 1210),
  ('5v4 chain reaction press near the sideline', 'defending', 'overload', 'out_of_possession', 208, 208, 'Defending Tactical Situation 2: Practice 2', 'Guardiola (Barcelona)', 'Back line and holding midfielder press hard in the first phase and outnumber the ball side.', 'Reds in a 4-1 shape against whites in a 4-3 shape on half a pitch; a red line across the back; coach in a small box with balls behind the whites.', 'Coach decides the side by passing to one of the white midfielders. Whites score a point by dribbling or receiving beyond the red line (offside on) and another by scoring past the keeper; if stopped on one side they can attack again with all players but must finish within 15 seconds. Reds win it and get the ball to the coach within 4 passes.', 'Offside applies; 15 second limit on second phase; reds max 4 passes.', 'Add one more white forward.', 'Full backs only step up if timing is right, otherwise wait for the No.6 to press; constant talk so the No.6 reads the picture.', '5v4 (+GK)', 10, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 1220),
  ('Closing down the full backs 9v10 two-zone game', 'defending', 'opposed', 'out_of_possession', 209, 209, 'Defending Tactical Situation 2: Practice 3', 'Guardiola (Barcelona)', 'Back line and midfield chain react to close down full backs and outnumber the ball zone.', 'Area split into a high zone and a low zone; low zone holds a 4v4 with two 10x10 yard blue boxes for the white full backs; high zone has 3 white forwards v 4 red defenders.', 'Whites must make at least 2 passes in the low zone before playing a full back, then attack through him, after which all can move freely. Red full backs only step out if the timing is right; otherwise the attacking midfielders close down. Reds who win it score using up to 5 passes.', '2 passes before playing the full back; reds max 5 passes.', NULL, 'Short distances and synchronised movement; full back decides whether to press his opponent.', '9v10 (+GKs)', 19, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 1230),
  ('Forcing the ball wide as a compact unit', 'defending', 'passive', 'out_of_possession', 212, 212, 'Defending Tactical Situation 3: Practice 1', 'Guardiola (Barcelona)', 'Midfield and forward chain moves as one to block forward passes and steer the ball to the touchline.', 'Two 5x5 yard blue boxes on the halfway line by the sidelines for the white wingers and two small cone goals; white back line on blue cones, reds in front.', 'Whites pass slowly then faster across the back; reds shift with the ball and block passes to the cone goals. When a winger receives in his box he is double marked and two more reds move over to outnumber the ball area. Reds take positions only and do not try to win the ball.', 'Reds do not try to win the ball.', NULL, 'Keep short distances between players.', 'White back 4 + GK + 2 wingers v red unit', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1240),
  ('8v10 dynamic pressing and counter game', 'defending', 'opposed', 'out_of_possession', 213, 213, 'Defending Tactical Situation 3: Practice 2', 'Guardiola (Barcelona)', 'Block forward passes, force the ball wide and double mark near the sideline.', '8v10 with two small cone goals inside the area and a red zone outside it for the white forward.', 'Whites score by passing through a cone goal or by finding the striker, who must control in the red zone; no long balls. Reds press to force it wide and double mark, then counter with up to 5 passes. Out of play restarts with the white keeper.', 'Whites no long passes; striker must control inside red zone; reds max 5 passes.', NULL, 'Short distances; synchronised pressing movements.', '8v10', 18, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 1250),
  ('11v11 superiority around the ball zonal game', 'defending', 'opposed', 'out_of_possession', 214, 214, 'Defending Tactical Situation 3: Practice 3', 'Guardiola (Barcelona)', 'Force the ball wide and outnumber the ball carrier near the sideline.', '11v11 in two thirds of a pitch with a 35x35 yard white zone in front of the red goal.', 'White keeper starts to a defender. Whites must string 2+ passes in the white zone, keep it there over 4 seconds and then score. Reds force the ball wide, overload the touchline and double mark, then counter with up to 5 passes.', 'Reds max 5 passes on the counter.', NULL, 'Outnumber near the sideline and double mark; talk and stay connected between lines.', '11v11', 22, 22, '2/3 pitch; white zone 35 x 35 yards', NULL, NULL, NULL, true, true, true, NULL, 1260),
  ('Pressing in three stages game with four zones', 'defending', 'opposed', 'out_of_possession', 215, 216, 'Defending Tactical Situation 3: Practice 4', 'Guardiola (Barcelona)', 'Press in stages to block forward passes and steer the ball to the sideline.', '11v11 in two thirds of a pitch: a 10x50 yard blue band outside the white box and a 35x35 yard white zone in front of the red goal; red striker starts on a yellow cone.', 'Whites earn a point each for passing forward from the blue band into the white zone, switching to the red weak side (not via the keeper) and scoring, so up to 3 per attack. Red striker presses the centre back first; reds force it wide, close space, double mark, then counter in 5 passes. Restart from the white keeper with the striker back on his cone.', 'Up to 3 points per white attack; reds max 5 passes.', 'Practice 5 (variation): same game but the attacking midfielder presses first; the striker stands on one of two yellow cones and the keeper restarts to the opposite side.', NULL, '11v11', 22, 22, '2/3 pitch; blue zone 10 x 50 yards; white zone 35 x 35 yards', NULL, NULL, NULL, true, true, true, NULL, 1270),
  ('Chain reactions to stop forward passes', 'defending', 'opposed', 'out_of_possession', 219, 219, 'Defending Tactical Situation 4: Practice 1', 'Guardiola (Barcelona)', 'Press the centre backs at the right moment so they have no time or space to play forward.', 'Half pitch with two 5x10 yard blue boxes for the white full backs and a 5x35 yard white zone near halfway for the white wingers; reds on blue cones, striker on one of two yellow cones.', 'White keeper plays to the side away from the red striker and the red winger presses the centre back first. Whites try to reach the full backs directly or via the wingers to score a point; if no option they play back to the keeper and restart.', 'Whites stay in their zones; no long passes.', NULL, 'Take up correct defensive positions; short distances and synchronised moves; striker stays close to the midfield.', 'White back 4 + 4 + GK v red 6 + striker', NULL, NULL, 'Half pitch', NULL, NULL, NULL, false, true, true, NULL, 1280),
  ('Stopping forward passes with central overload', 'defending', 'opposed', 'out_of_possession', 220, 220, 'Defending Tactical Situation 4: Practice 2', 'Guardiola (Barcelona)', 'Deny the centre backs forward passes and outnumber the central zone.', 'As practice 1 with a 15x35 yard red zone added in the centre.', 'White keeper builds to the side away from the striker; the red winger presses first. Whites aim to find the full backs in the blue boxes or the wingers in the white zone, directly or through the midfielders in the red zone. Reds win it and counter with up to 5 passes.', 'Whites may not leave the red central zone while attacking; no long passes; reds max 5 passes.', NULL, 'Short distances; no time or space for opponents in the red area; striker drops close for double marking.', 'White back 4 + 6 + GK v reds', NULL, NULL, 'Half pitch; red zone 15 x 35 yards', NULL, NULL, NULL, false, true, true, NULL, 1290),
  ('Body shape to limit centre back passing angles', 'defending', 'opposed', 'out_of_possession', 221, 221, 'Defending Tactical Situation 4: Practice 3', 'Guardiola (Barcelona)', 'Use body shape and timing to close passing angles from the centre backs.', '9v10 small sided game with two 5x25 yard blue boxes near the sidelines for the white full backs; red striker on one of two yellow cones.', 'White keeper plays to the side away from the striker and the red winger presses first. Full backs can carry forward freely inside their box but can be pressed once outside. Reds who win it counter in up to 5 passes.', 'No long passes for whites; full backs stay in boxes until they receive; reds max 5 passes.', NULL, 'Correct defensive positions; striker stays near the midfield to double mark.', '9v10', 19, 21, 'Blue zones 5 x 25 yards', NULL, NULL, NULL, true, true, true, NULL, 1300),
  ('Defending when pressure is not possible', 'defending', 'opposed', 'out_of_possession', 224, 224, 'Defending Tactical Situation 5: Practice 1', 'Guardiola (Barcelona)', 'Block vertical and diagonal passes when the centre cannot be pressed.', '30x40 yard area of four coloured zones: a 15x30 white area split in three for 3 red midfielders, a 5x30 blue strip for the red striker, a 10x30 yellow zone with 2 white midfielders and a 5x20 red zone with 2 white forwards; 2 white defenders outside.', 'White defenders pass slowly and look to find the midfielders, who turn and look to play into the forwards. Reds shift with the ball inside their own areas; once a white midfielder receives, the red midfielders may move freely to block the pass.', 'White midfielders 2 touches and must pass from inside the yellow zone; reds stay in areas until a midfielder receives.', NULL, 'Read the situation and position to cut off vertical and diagonal passes.', '2+2+2 whites v 3+1 reds', 10, 10, '30 x 40 yards', 36.6, 27.4, NULL, false, false, true, NULL, 1310),
  ('No-pressure defending in the centre 3-zone game', 'defending', 'opposed', 'out_of_possession', 225, 225, 'Defending Tactical Situation 5: Practice 2', 'Guardiola (Barcelona)', 'Defend the centre and block through balls when the man on the ball cannot be pressed.', 'Two thirds of a pitch with three zones: 2 white defenders outside the blue area, a red forward and 2 white midfielders in the red area, and 2 red centre backs, a red No.6 and 2 white forwards in the white area (3v2).', 'White centre backs pass then find a midfielder in the red area, which opens play into an 8v8 phase where all move freely. The ball carrier looks for a final pass to a forward in the white area. Reds win it and complete 5 passes.', 'Point if a midfielder plays a through pass into the white area; a goal after that counts triple; white centre backs not in the second phase.', NULL, 'Synchronised movement to stay cohesive; talk and keep distances short.', '8v8 (+GK)', 17, 17, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 1320),
  ('No-pressure defending in the centre 6v3 build', 'defending', 'opposed', 'out_of_possession', 226, 226, 'Defending Tactical Situation 5: Practice 3', 'Guardiola (Barcelona)', 'Defend centrally when the ball cannot be pressed, forcing play wide.', 'White low zone 25 yards long with 6 whites v 3 reds, a yellow neutral band reds cannot enter, and a red zone in front of the red goal where two red midfielders and the back line start (3v2).', 'Whites keep it and dribble over the red line between the yellow cones into the neutral band, which starts phase two where all move freely and whites have 10 seconds to score. Final pass into the red area scores a point; a goal after that counts triple. Reds block, steer to the sideline, then counter in up to 5 passes.', '10 seconds to score in phase two; reds max 5 passes; restart from white keeper.', NULL, NULL, '6v3 low zone; full game about 10v10', 20, 22, 'Low zone 25 yards long', NULL, NULL, NULL, true, true, true, NULL, 1330),
  ('Defending an opponent free on the flank', 'defending', 'passive', 'out_of_possession', 229, 229, 'Defending Tactical Situation 6: Practice 1', 'Guardiola (Barcelona)', 'Drop off and then step up together when a full back has time on the ball near the sideline.', 'Red back four, midfield and keeper in front of goal; two white full backs and two white midfielders around halfway with a coach and balls behind.', 'Coach feeds a white full back who carries forward while reds drop to buy time for the attacking midfielder to close him. Once closed he passes back to a midfielder and reds step up together, stopping when the ball arrives; ball returns to the coach and reds push out to restart.', NULL, NULL, 'Read the situation with synchronised vertical moves; talk to keep cohesion and balance.', 'Red defensive unit + GK v 4 whites + coach', NULL, NULL, NULL, NULL, NULL, NULL, false, true, false, NULL, 1340),
  ('Defending near the sideline when pressing fails', 'defending', 'opposed', 'out_of_possession', 230, 230, 'Defending Tactical Situation 6: Practice 2', 'Guardiola (Barcelona)', 'Block passes inside when the wide ball carrier cannot be pressed.', 'Two thirds of a pitch with two 15x10 yard red zones by the sidelines holding the white full backs and red wingers, and a 15x35 yard white zone in front of goal.', 'Coach plays to a white full back, who is allowed to dribble past the red winger; the strong-side attacking midfielder (or No.6) closes him and shuts off inside options. Then all join in an 8v9 attack; reds block passes into the white zone, win it and complete 5 straight passes.', 'Pass into the white zone scores; goal after it in the same move counts triple; reds win by 5 consecutive passes.', NULL, 'Position to block passes towards the inside.', '8v9 (+GK)', 18, 18, '2/3 pitch; red zones 15 x 10 yards; white zone 15 x 35 yards', NULL, NULL, NULL, true, true, true, NULL, 1350),
  ('Sideline defending 6v3 build and break', 'defending', 'opposed', 'out_of_possession', 231, 231, 'Defending Tactical Situation 6: Practice 3', 'Guardiola (Barcelona)', 'Defend near the touchlines when pressing is not possible, forcing play wide.', '25x50 yard white low zone with 6v3, a yellow neutral band reds cannot enter, and a 20x45 yard red area in front of goal where red midfielders 8 and 6 start (5v2).', 'Whites keep it and dribble over the red line into the yellow band, which starts phase two where all move freely. A pass into the red zone scores one; a goal in the same move counts triple. Reds block, push it wide and counter in up to 5 passes.', 'Reds max 5 passes; restart from white keeper.', NULL, NULL, '6v3 low zone; full game about 10v10', 20, 22, 'White zone 25 x 50 yards; red area 20 x 45 yards', NULL, NULL, NULL, true, true, true, NULL, 1360),
  ('2v2 flank defending and box positions', 'defending', 'opposed', 'out_of_possession', 234, 234, 'Defending Tactical Situation 7: Practice 1', 'Guardiola (Barcelona)', 'Stop flank overloads after a switch and take up correct box positions to deal with crosses.', 'Half pitch with two 10x35 yard blue zones on the flanks; coach with balls in the centre.', 'Coach plays to a white full back; reds shift to the ball. When the strong-side holding midfielder receives he switches long to the weak side to cross and score; red full back and winger defend the 2v2 in the blue zone against overlaps and inside runs while the rest set up in the box. Reds let the cross in to practise defending it.', NULL, 'Add an extra forward to the white team.', NULL, '2v2 on the flank within full unit', NULL, NULL, 'Half pitch; blue zones 10 x 35 yards', NULL, NULL, NULL, true, true, true, NULL, 1370),
  ('3v3 flank defending in a 3 zone dynamic game', 'defending', 'opposed', 'out_of_possession', 235, 235, 'Defending Tactical Situation 7: Practice 2', 'Guardiola (Barcelona)', 'Prevent numerical advantage on the flanks and defend crosses after a switch.', 'Half pitch split into three equal zones with small goals near the sidelines; coach outside; white full backs start on blue cones.', 'Coach plays to a white centre back and the nearest white No.8 joins the side zone for a 3v2 (reds leave the weak side empty). Once all three whites have touched it or a centre back dribbles over the red line, the coach switches long to the far side and phase two begins: all move freely, whites try to score and reds defend the cross.', 'Once reds win it all zone limits go; they attack the small goals with up to 5 passes.', NULL, NULL, '3v3 / 3v2 zones within about 9v9', NULL, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 1380),
  ('9v10 quick reactions on the weak side', 'defending', 'opposed', 'out_of_possession', 236, 236, 'Defending Tactical Situation 7: Practice 3', 'Guardiola (Barcelona)', 'React collectively to switches and stop flank overloads.', '9v10 in three equal-width zones; reds in a 4-1-3, whites in a 4-2-3.', 'When whites move the ball into a blue side zone the reds must empty the opposite side zone within 3 seconds. Whites look to exploit this with quick long switches to the weak side.', 'Reds vacate weak side zone within 3 seconds.', NULL, 'Short distances; talk and move together; wingers control the full backs.', '9v10', 19, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 1390),
  ('Outnumber wide and defend crosses in the box', 'defending', 'passive', 'out_of_possession', 239, 240, 'Defending Tactical Situation 8: Practice 1', 'Guardiola (Barcelona)', 'Create superiority near the sideline and keep numbers in the box against crosses.', 'Zone in front of goal with red defenders and keeper; white wingers inside the zone, white full backs and midfielders outside it.', 'Whites pass outside the zone; when a winger receives inside it he carries forward and crosses. Reds slide to the ball without tackling, outnumbering the winger with the holding midfielder (situation 1) or a centre back (situation 2), and set up in the box to defend the cross.', 'Reds do not try to win the ball or block the cross.', NULL, 'Whites pass short and in sequence so reds can shift; the No.6 creates the overload when near the strong side.', 'Red back four + No.6 + GK v whites', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 1400),
  ('5v5+2 preventing the cross with a 2v1', 'defending', 'opposed', 'out_of_possession', 241, 241, 'Defending Tactical Situation 8: Practice 2', 'Guardiola (Barcelona)', 'Double up near the sideline to stop crosses and defend the box.', 'Half pitch with two yellow zones near the sidelines and a full-width blue zone; 5v5 plus 2 outside players; coach in a red area.', 'Whites use the outside players to get the ball into a yellow zone and cross. Red full backs follow their man into the yellow zone but may only tackle once a second red is inside the zone; reds also defend the cross. Reds who win it find the coach within 4 passes.', 'No long passes for whites; tackle only with a 2v1 in the yellow zone; reds max 4 passes.', NULL, 'The second defender calls when he arrives so the first knows he can tackle.', '5v5 + 2', 12, 13, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 1410),
  ('8v9 high flank overload to block crosses', 'defending', 'opposed', 'out_of_possession', 242, 242, 'Defending Tactical Situation 8: Practice 3', 'Guardiola (Barcelona)', 'Outnumber the ball high on the flank and in the box to stop or deal with crosses.', 'Area a bit bigger than half a pitch with two yellow zones near the sidelines; reds 4-1-2, whites 3-3-2.', 'Whites build through the flanks into the yellow zones and cross. Reds create overloads in the yellow zones and the box to win it or clear the cross, then counter in up to 5 passes.', 'Whites no long passes; reds max 5 passes.', NULL, 'Short distances and synchronised moves; good communication.', '8v9', 17, 19, 'Slightly more than half pitch', NULL, NULL, NULL, true, true, true, NULL, 1420)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'fc-barcelona-training-sessions-160-practices-from-34-tactical-situations') b;
INSERT INTO schema_migrations (filename) VALUES ('2410-exercises-book-fc-barcelona-training-sessions-160-practices-from-34-tactica.sql') ON CONFLICT DO NOTHING;
